window.calculatePhysicsAcceleration = function () {

    const v1 = Number(
        document.getElementById("physicsAccelerationV1")?.value
    );

    const v2 = Number(
        document.getElementById("physicsAccelerationV2")?.value
    );

    const t = Number(
        document.getElementById("physicsAccelerationTime")?.value
    );

    const result =
        document.getElementById("physicsAccelerationResult");

    if (!result) return;

    if (!Number.isFinite(v1) ||
        !Number.isFinite(v2) ||
        !Number.isFinite(t)) {

        result.innerHTML = "â‌Œ ط£ط¯ط®ظ„ ط¬ظ…ظٹط¹ ط§ظ„ظ‚ظٹظ…";
        return;
    }

    if (t === 0) {

        result.innerHTML =
            "â‌Œ ط§ظ„ط²ظ…ظ† ظ„ط§ ظٹظ…ظƒظ† ط£ظ† ظٹط³ط§ظˆظٹ طµظپط±";

        return;
    }

    const acceleration = (v2 - v1) / t;

    result.innerHTML =
        `âœ… a = ${acceleration} m/sآ²`;

    console.log(
        "ًںڈژï¸ڈ ACCELERATION:",
        acceleration,
        "m/sآ²"
    );
};

