window.calculatePhysicsPower = function () {

    const work =
        parseFloat(
            document.getElementById("physicsPowerWork")?.value
        );

    const time =
        parseFloat(
            document.getElementById("physicsPowerTime")?.value
        );

    const result =
        document.getElementById("physicsPowerResult");

    if (!Number.isFinite(work) ||
        !Number.isFinite(time)) {

        result.innerHTML =
            "âڑ ï¸ڈ ط£ط¯ط®ظ„ ط§ظ„ط´ط؛ظ„ ظˆط§ظ„ط²ظ…ظ† ط£ظˆظ„ط§ظ‹";

        return;
    }

    if (time === 0) {

        result.innerHTML =
            "â‌Œ ط§ظ„ط²ظ…ظ† ظ„ط§ ظٹظ…ظƒظ† ط£ظ† ظٹط³ط§ظˆظٹ طµظپط±";

        return;
    }

    const power = work / time;

    result.innerHTML =
        `âœ… P = ${power.toFixed(6)} W`;
};
