window.calculatePhysicsElectricalPower = function () {

    const voltage =
        parseFloat(
            document.getElementById("physicsEPVoltage")?.value
        );

    const current =
        parseFloat(
            document.getElementById("physicsEPCurrent")?.value
        );

    const resistance =
        parseFloat(
            document.getElementById("physicsEPResistance")?.value
        );

    const result =
        document.getElementById("physicsEPResult");

    const hasV = Number.isFinite(voltage);
    const hasI = Number.isFinite(current);
    const hasR = Number.isFinite(resistance);

    // V + I
    if (hasV && hasI) {

        const power = voltage * current;

        result.innerHTML =
            `âœ… P = ${power.toFixed(6)} W`;

        return;
    }

    // I + R
    if (hasI && hasR) {

        const power = current * current * resistance;

        result.innerHTML =
            `âœ… P = ${power.toFixed(6)} W`;

        return;
    }

    // V + R
    if (hasV && hasR) {

        if (resistance === 0) {

            result.innerHTML =
                "â‌Œ ط§ظ„ظ…ظ‚ط§ظˆظ…ط© ظ„ط§ ظٹظ…ظƒظ† ط£ظ† طھط³ط§ظˆظٹ طµظپط±";

            return;
        }

        const power =
            (voltage * voltage) / resistance;

        result.innerHTML =
            `âœ… P = ${power.toFixed(6)} W`;

        return;
    }

    result.innerHTML =
        "âڑ ï¸ڈ ط£ط¯ط®ظ„ ط£ظٹ ظ‚ظٹظ…طھظٹظ† ظ…ظ† V ظˆ I ظˆ R";
};
