// ==========================================

window.calculateParallelResistance = function () {

    const count =
        parseInt(
            document.getElementById("parallelCount")?.value
        );

    const result =
        document.getElementById("parallelResult");

    if (!result) return;

    if (!Number.isInteger(count) || count < 1) {

        result.innerHTML =
            "âڑ ï¸ڈ ط£ط¯ط®ظ„ ط¹ط¯ط¯ظ‹ط§ طµط­ظٹط­ظ‹ط§ ظ„ظ„ظ…ظ‚ط§ظˆظ…ط§طھ";

        return;
    }

    let reciprocalTotal = 0;

    for (let i = 1; i <= count; i++) {

        const field =
            document.getElementById(`parallelR${i}`);

        const value =
            parseFloat(field?.value);

        if (!Number.isFinite(value)) {

            result.innerHTML =
                `âڑ ï¸ڈ ط£ط¯ط®ظ„ ظ‚ظٹظ…ط© R${i}`;

            return;
        }

        if (value <= 0) {

            result.innerHTML =
                `â‌Œ ظ‚ظٹظ…ط© R${i} ظٹط¬ط¨ ط£ظ† طھظƒظˆظ† ط£ظƒط¨ط± ظ…ظ† طµظپط±`;

            return;
        }

        reciprocalTotal += 1 / value;
    }

    const total =
        1 / reciprocalTotal;

    result.innerHTML =
        `âœ… Rt = ${total.toFixed(6)} خ©`;
};
