// ==========================================
// ًں§® ط­ط³ط§ط¨ KCL
// ==========================================

window.calculateKCL = function () {

    const input =
        document.getElementById("kclIn")?.value || "";

    const output =
        document.getElementById("kclOut")?.value || "";

    const result =
        document.getElementById("kclResult");

    const incoming =
        input.split(",")
            .map(Number)
            .filter(Number.isFinite);

    const outgoing =
        output.split(",")
            .map(Number)
            .filter(Number.isFinite);

    if (!incoming.length || !outgoing.length) {

        result.innerHTML =
            "âڑ ï¸ڈ ط£ط¯ط®ظ„ ط§ظ„طھظٹط§ط±ط§طھ ظ…ظپطµظˆظ„ط© ط¨ظپظˆط§طµظ„";

        return;
    }

    const sumIn =
        incoming.reduce((a, b) => a + b, 0);

    const sumOut =
        outgoing.reduce((a, b) => a + b, 0);

    const difference =
        sumIn - sumOut;

    if (Math.abs(difference) < 1e-10) {

        result.innerHTML =
            `âœ… KCL طµط­ظٹط­<br>
             ط§ظ„ط¯ط§ط®ظ„ = ${sumIn.toFixed(6)} A<br>
             ط§ظ„ط®ط§ط±ط¬ = ${sumOut.toFixed(6)} A`;

    } else {

        result.innerHTML =
            `â‌Œ KCL ط؛ظٹط± ظ…طھط­ظ‚ظ‚<br>
             ط§ظ„ط¯ط§ط®ظ„ = ${sumIn.toFixed(6)} A<br>
             ط§ظ„ط®ط§ط±ط¬ = ${sumOut.toFixed(6)} A<br>
             ط§ظ„ظپط±ظ‚ = ${difference.toFixed(6)} A`;
    }
};


