window.calculatePhysicsElectromagneticInduction = function () {

    const N =
        parseFloat(
            document.getElementById("physicsEMIN")?.value
        );

    const flux =
        parseFloat(
            document.getElementById("physicsEMIFlux")?.value
        );

    const time =
        parseFloat(
            document.getElementById("physicsEMITime")?.value
        );

    const result =
        document.getElementById("physicsEMIResult");

    if (!Number.isFinite(N) ||
        !Number.isFinite(flux) ||
        !Number.isFinite(time)) {

        result.innerHTML =
            "âڑ ï¸ڈ ط£ط¯ط®ظ„ ط¹ط¯ط¯ ط§ظ„ظ„ظپط§طھ ظˆط§ظ„ظپظٹط¶ ظˆط§ظ„ط²ظ…ظ† ط£ظˆظ„ط§ظ‹";

        return;
    }

    if (N < 0) {

        result.innerHTML =
            "â‌Œ ط¹ط¯ط¯ ط§ظ„ظ„ظپط§طھ ظ„ط§ ظٹظ…ظƒظ† ط£ظ† ظٹظƒظˆظ† ط³ط§ظ„ط¨ظ‹ط§";

        return;
    }

    if (time === 0) {

        result.innerHTML =
            "â‌Œ ط§ظ„ط²ظ…ظ† ظ„ط§ ظٹظ…ظƒظ† ط£ظ† ظٹط³ط§ظˆظٹ طµظپط±";

        return;
    }

    const emf =
        -(N * flux) / time;

    result.innerHTML =
        `âœ… خµ = ${emf.toFixed(6)} V`;
};
