window.calculatePhysicsSpecificHeat = function () {

    const Q = Number(
        document.getElementById("physicsSpecificHeatQ")?.value
    );

    const m = Number(
        document.getElementById("physicsSpecificHeatMass")?.value
    );

    const deltaT = Number(
        document.getElementById("physicsSpecificHeatDeltaT")?.value
    );

    const result =
        document.getElementById("physicsSpecificHeatResult");

    if (!result) return;

    if (
        !Number.isFinite(Q) ||
        !Number.isFinite(m) ||
        !Number.isFinite(deltaT)
    ) {
        result.innerHTML = "âڑ ï¸ڈ ط£ط¯ط®ظ„ ط¬ظ…ظٹط¹ ط§ظ„ظ‚ظٹظ…";
        return;
    }

    if (m === 0) {
        result.innerHTML = "â‌Œ ط§ظ„ظƒطھظ„ط© ظ„ط§ ظٹظ…ظƒظ† ط£ظ† طھط³ط§ظˆظٹ طµظپط±ظ‹ط§";
        return;
    }

    if (deltaT === 0) {
        result.innerHTML =
            "â‌Œ ط§ظ„طھط؛ظٹط± ظپظٹ ط¯ط±ط¬ط© ط§ظ„ط­ط±ط§ط±ط© ظ„ط§ ظٹظ…ظƒظ† ط£ظ† ظٹط³ط§ظˆظٹ طµظپط±ظ‹ط§";
        return;
    }

    const c = Q / (m * deltaT);

    result.innerHTML =
        `âœ… c = ${c.toFixed(6)} J/kgآ·آ°C`;
};
