window.calculatePhysicsThermalExpansion = function () {

    const L0 = Number(
        document.getElementById("physicsExpansionLength")?.value
    );

    const alpha = Number(
        document.getElementById("physicsExpansionAlpha")?.value
    );

    const deltaT = Number(
        document.getElementById("physicsExpansionDeltaT")?.value
    );

    const result =
        document.getElementById("physicsExpansionResult");

    if (!result) return;

    if (
        !Number.isFinite(L0) ||
        !Number.isFinite(alpha) ||
        !Number.isFinite(deltaT)
    ) {
        result.innerHTML = "âڑ ï¸ڈ ط£ط¯ط®ظ„ ط¬ظ…ظٹط¹ ط§ظ„ظ‚ظٹظ…";
        return;
    }

    if (L0 < 0) {
        result.innerHTML =
            "â‌Œ ط§ظ„ط·ظˆظ„ ط§ظ„ط£طµظ„ظٹ ظ„ط§ ظٹظ…ظƒظ† ط£ظ† ظٹظƒظˆظ† ط³ط§ظ„ط¨ظ‹ط§";
        return;
    }

    if (alpha < 0) {
        result.innerHTML =
            "â‌Œ ظ…ط¹ط§ظ…ظ„ ط§ظ„طھظ…ط¯ط¯ ظ„ط§ ظٹظ…ظƒظ† ط£ظ† ظٹظƒظˆظ† ط³ط§ظ„ط¨ظ‹ط§";
        return;
    }

    const deltaL = alpha * L0 * deltaT;
    const finalLength = L0 + deltaL;

    result.innerHTML = `
        âœ… خ”L = ${deltaL.toFixed(6)} m<br>
        ًں“ڈ L = ${finalLength.toFixed(6)} m
    `;
};
