// ًں§® ط­ط³ط§ط¨ ظ‚ط§ظ†ظˆظ† ط§ظ„ط؛ط§ط²ط§طھ
// ==========================================

window.calculatePhysicsGasLaw = function () {

    const unknown =
        document.getElementById("physicsGasUnknown")?.value;

    const ids = [
        "P1",
        "V1",
        "T1",
        "P2",
        "V2",
        "T2"
    ];

    const values = {};

    for (const id of ids) {

        const element =
            document.getElementById("physicsGas" + id);

        if (id === unknown) {
            continue;
        }

        const value = Number(element?.value);

        if (!Number.isFinite(value)) {
            document.getElementById("physicsGasResult").innerHTML =
                "âڑ ï¸ڈ ط£ط¯ط®ظ„ ط¬ظ…ظٹط¹ ط§ظ„ظ‚ظٹظ… ط§ظ„ظ…ط·ظ„ظˆط¨ط©";
            return;
        }

        values[id] = value;
    }

    const result =
        document.getElementById("physicsGasResult");

    let answer;

    switch (unknown) {

        case "P1":
            if (values.V1 === 0 || values.T1 === 0) {
                result.innerHTML = "â‌Œ ظ„ط§ ظٹظ…ظƒظ† ط§ظ„ظ‚ط³ظ…ط© ط¹ظ„ظ‰ طµظپط±";
                return;
            }

            answer =
                (values.P2 * values.V2 * values.T1) /
                (values.V1 * values.T2);
            break;

        case "V1":
            if (values.P1 === 0 || values.T1 === 0) {
                result.innerHTML = "â‌Œ ظ„ط§ ظٹظ…ظƒظ† ط§ظ„ظ‚ط³ظ…ط© ط¹ظ„ظ‰ طµظپط±";
                return;
            }

            answer =
                (values.P2 * values.V2 * values.T1) /
                (values.P1 * values.T2);
            break;

        case "T1":
            if (values.P1 === 0 || values.V1 === 0) {
                result.innerHTML = "â‌Œ ظ„ط§ ظٹظ…ظƒظ† ط§ظ„ظ‚ط³ظ…ط© ط¹ظ„ظ‰ طµظپط±";
                return;
            }

            answer =
                (values.P1 * values.V1 * values.T2) /
                (values.P2 * values.V2);
            break;

        case "P2":
            if (values.V2 === 0 || values.T1 === 0) {
                result.innerHTML = "â‌Œ ظ„ط§ ظٹظ…ظƒظ† ط§ظ„ظ‚ط³ظ…ط© ط¹ظ„ظ‰ طµظپط±";
                return;
            }

            answer =
                (values.P1 * values.V1 * values.T2) /
                (values.V2 * values.T1);
            break;

        case "V2":
            if (values.P2 === 0 || values.T1 === 0) {
                result.innerHTML = "â‌Œ ظ„ط§ ظٹظ…ظƒظ† ط§ظ„ظ‚ط³ظ…ط© ط¹ظ„ظ‰ طµظپط±";
                return;
            }

            answer =
                (values.P1 * values.V1 * values.T2) /
                (values.P2 * values.T1);
            break;

        case "T2":
            if (values.P2 === 0 || values.V2 === 0) {
                result.innerHTML = "â‌Œ ظ„ط§ ظٹظ…ظƒظ† ط§ظ„ظ‚ط³ظ…ط© ط¹ظ„ظ‰ طµظپط±";
                return;
            }

            answer =
                (values.P2 * values.V2 * values.T1) /
                (values.P1 * values.V1);
            break;
    }

    if (!Number.isFinite(answer)) {
        result.innerHTML = "â‌Œ ظ„ط§ ظٹظ…ظƒظ† ط­ط³ط§ط¨ ط§ظ„ظ†طھظٹط¬ط© ط¨ظ‡ط°ظ‡ ط§ظ„ظ‚ظٹظ…";
        return;
    }

    result.innerHTML =
        `âœ… ${unknown} = ${answer.toFixed(6)}`;
};
