window.calculatePhysicsPressureTemperature = function () {

    const unknown =
        document.getElementById("physicsPTUnknown")?.value;

    const ids = ["P1", "T1", "P2", "T2"];

    const values = {};

    for (const id of ids) {

        if (id === unknown) continue;

        const element =
            document.getElementById("physicsPT" + id);

        const value = Number(element?.value);

        if (!Number.isFinite(value)) {

            document.getElementById("physicsPTResult").innerHTML =
                "âڑ ï¸ڈ ط£ط¯ط®ظ„ ط¬ظ…ظٹط¹ ط§ظ„ظ‚ظٹظ… ط§ظ„ظ…ط·ظ„ظˆط¨ط©";

            return;
        }

        values[id] = value;
    }

    const result =
        document.getElementById("physicsPTResult");

    let answer;

    switch (unknown) {

        case "P1":

            if (values.T1 === 0) {
                result.innerHTML =
                    "â‌Œ ط¯ط±ط¬ط© ط§ظ„ط­ط±ط§ط±ط© ظ„ط§ ظٹظ…ظƒظ† ط£ظ† طھط³ط§ظˆظٹ طµظپط±ظ‹ط§";
                return;
            }

            answer =
                (values.P2 * values.T1) /
                values.T2;

            break;

        case "T1":

            if (values.P2 === 0) {
                result.innerHTML =
                    "â‌Œ ط§ظ„ط¶ط؛ط· ظ„ط§ ظٹظ…ظƒظ† ط£ظ† ظٹط³ط§ظˆظٹ طµظپط±ظ‹ط§";
                return;
            }

            answer =
                (values.P1 * values.T2) /
                values.P2;

            break;

        case "P2":

            if (values.T1 === 0) {
                result.innerHTML =
                    "â‌Œ ط¯ط±ط¬ط© ط§ظ„ط­ط±ط§ط±ط© ظ„ط§ ظٹظ…ظƒظ† ط£ظ† طھط³ط§ظˆظٹ طµظپط±ظ‹ط§";
                return;
            }

            answer =
                (values.P1 * values.T2) /
                values.T1;

            break;

        case "T2":

            if (values.P1 === 0) {
                result.innerHTML =
                    "â‌Œ ط§ظ„ط¶ط؛ط· ظ„ط§ ظٹظ…ظƒظ† ط£ظ† ظٹط³ط§ظˆظٹ طµظپط±ظ‹ط§";
                return;
            }

            answer =
                (values.P2 * values.T1) /
                values.P1;

            break;
    }

    if (!Number.isFinite(answer)) {

        result.innerHTML =
            "â‌Œ ظ„ط§ ظٹظ…ظƒظ† ط­ط³ط§ط¨ ط§ظ„ظ†طھظٹط¬ط© ط¨ظ‡ط°ظ‡ ط§ظ„ظ‚ظٹظ…";

        return;
    }

    result.innerHTML =
        `âœ… ${unknown} = ${answer.toFixed(6)}`;
};
