// ًں§® ط­ط³ط§ط¨ ظ‚ط§ظ†ظˆظ† ط§ظ„ط؛ط§ط² ط§ظ„ظ…ط«ط§ظ„ظٹ
// ==========================================

window.calculatePhysicsIdealGas = function () {

    const unknown =
        document.getElementById("physicsIdealUnknown")?.value;

    const result =
        document.getElementById("physicsIdealResult");

    if (!result) return;

    const getValue = id => {

        const element =
            document.getElementById("physicsIdeal" + id);

        return Number(element?.value);
    };

    const R = getValue("R");

    if (!Number.isFinite(R) || R <= 0) {
        result.innerHTML =
            "â‌Œ ط«ط§ط¨طھ ط§ظ„ط؛ط§ط² R ظٹط¬ط¨ ط£ظ† ظٹظƒظˆظ† ط£ظƒط¨ط± ظ…ظ† طµظپط±";
        return;
    }

    let answer;

    switch (unknown) {

        case "P": {

            const V = getValue("V");
            const n = getValue("N");
            const T = getValue("T");

            if (
                !Number.isFinite(V) ||
                !Number.isFinite(n) ||
                !Number.isFinite(T)
            ) {
                result.innerHTML =
                    "âڑ ï¸ڈ ط£ط¯ط®ظ„ ط¬ظ…ظٹط¹ ط§ظ„ظ‚ظٹظ… ط§ظ„ظ…ط·ظ„ظˆط¨ط©";
                return;
            }

            if (V === 0) {
                result.innerHTML =
                    "â‌Œ ط§ظ„ط­ط¬ظ… ظ„ط§ ظٹظ…ظƒظ† ط£ظ† ظٹط³ط§ظˆظٹ طµظپط±ظ‹ط§";
                return;
            }

            answer = (n * R * T) / V;

            result.innerHTML =
                `âœ… P = ${answer.toFixed(6)} Pa`;

            return;
        }

        case "V": {

            const P = getValue("P");
            const n = getValue("N");
            const T = getValue("T");

            if (
                !Number.isFinite(P) ||
                !Number.isFinite(n) ||
                !Number.isFinite(T)
            ) {
                result.innerHTML =
                    "âڑ ï¸ڈ ط£ط¯ط®ظ„ ط¬ظ…ظٹط¹ ط§ظ„ظ‚ظٹظ… ط§ظ„ظ…ط·ظ„ظˆط¨ط©";
                return;
            }

            if (P === 0) {
                result.innerHTML =
                    "â‌Œ ط§ظ„ط¶ط؛ط· ظ„ط§ ظٹظ…ظƒظ† ط£ظ† ظٹط³ط§ظˆظٹ طµظپط±ظ‹ط§";
                return;
            }

            answer = (n * R * T) / P;

            result.innerHTML =
                `âœ… V = ${answer.toFixed(6)} mآ³`;

            return;
        }

        case "n": {

            const P = getValue("P");
            const V = getValue("V");
            const T = getValue("T");

            if (
                !Number.isFinite(P) ||
                !Number.isFinite(V) ||
                !Number.isFinite(T)
            ) {
                result.innerHTML =
                    "âڑ ï¸ڈ ط£ط¯ط®ظ„ ط¬ظ…ظٹط¹ ط§ظ„ظ‚ظٹظ… ط§ظ„ظ…ط·ظ„ظˆط¨ط©";
                return;
            }

            if (R === 0 || T === 0) {
                result.innerHTML =
                    "â‌Œ ظ„ط§ ظٹظ…ظƒظ† ط§ظ„ظ‚ط³ظ…ط© ط¹ظ„ظ‰ طµظپط±";
                return;
            }

            answer = (P * V) / (R * T);

            result.innerHTML =
                `âœ… n = ${answer.toFixed(6)} mol`;

            return;
        }

        case "T": {

            const P = getValue("P");
            const V = getValue("V");
            const n = getValue("N");

            if (
                !Number.isFinite(P) ||
                !Number.isFinite(V) ||
                !Number.isFinite(n)
            ) {
                result.innerHTML =
                    "âڑ ï¸ڈ ط£ط¯ط®ظ„ ط¬ظ…ظٹط¹ ط§ظ„ظ‚ظٹظ… ط§ظ„ظ…ط·ظ„ظˆط¨ط©";
                return;
            }

            if (n === 0 || R === 0) {
                result.innerHTML =
                    "â‌Œ ظ„ط§ ظٹظ…ظƒظ† ط§ظ„ظ‚ط³ظ…ط© ط¹ظ„ظ‰ طµظپط±";
                return;
            }

            answer = (P * V) / (n * R);

            result.innerHTML =
                `âœ… T = ${answer.toFixed(6)} K`;

            return;
        }
    }
};
