window.calculatePhysicsThermalEfficiency = function () {

    const work = Number(
        document.getElementById("physicsEfficiencyWork")?.value
    );

    const heatIn = Number(
        document.getElementById("physicsEfficiencyHeatIn")?.value
    );

    const result =
        document.getElementById("physicsEfficiencyResult");

    if (!result) return;

    if (
        !Number.isFinite(work) ||
        !Number.isFinite(heatIn)
    ) {
        result.innerHTML =
            "âڑ ï¸ڈ ط£ط¯ط®ظ„ ط¬ظ…ظٹط¹ ط§ظ„ظ‚ظٹظ…";
        return;
    }

    if (heatIn === 0) {
        result.innerHTML =
            "â‌Œ ط§ظ„ط­ط±ط§ط±ط© ط§ظ„ط¯ط§ط®ظ„ط© ظ„ط§ ظٹظ…ظƒظ† ط£ظ† طھط³ط§ظˆظٹ طµظپط±ظ‹ط§";
        return;
    }

    if (work < 0 || heatIn < 0) {
        result.innerHTML =
            "â‌Œ ط§ظ„ظ‚ظٹظ… ظ„ط§ ظٹظ…ظƒظ† ط£ظ† طھظƒظˆظ† ط³ط§ظ„ط¨ط©";
        return;
    }

    const efficiency =
        (work / heatIn) * 100;

    result.innerHTML =
        `âœ… خ· = ${efficiency.toFixed(6)} %`;
};
