window.calculatePhysicsHeatPower = function () {

    const Q = Number(
        document.getElementById("physicsHeatPowerQ")?.value
    );

    const t = Number(
        document.getElementById("physicsHeatPowerTime")?.value
    );

    const result =
        document.getElementById("physicsHeatPowerResult");

    if (!result) return;

    if (
        !Number.isFinite(Q) ||
        !Number.isFinite(t)
    ) {
        result.innerHTML =
            "âڑ ï¸ڈ ط£ط¯ط®ظ„ ط¬ظ…ظٹط¹ ط§ظ„ظ‚ظٹظ…";
        return;
    }

    if (t === 0) {
        result.innerHTML =
            "â‌Œ ط§ظ„ط²ظ…ظ† ظ„ط§ ظٹظ…ظƒظ† ط£ظ† ظٹط³ط§ظˆظٹ طµظپط±ظ‹ط§";
        return;
    }

    const power = Q / t;

    result.innerHTML =
        `âœ… P = ${power.toFixed(6)} W`;
};
