window.calculatePhysicsDensity = function () {

    const unknown =
        document.getElementById("physicsDensityUnknown")?.value;

    const result =
        document.getElementById("physicsDensityResult");

    if (!result) return;

    const getValue = id => {

        const element =
            document.getElementById("physicsDensity" + id);

        return Number(element?.value);
    };

    let answer;

    switch (unknown) {

        case "rho": {

            const m = getValue("Mass");
            const V = getValue("Volume");

            if (
                !Number.isFinite(m) ||
                !Number.isFinite(V)
            ) {
                result.innerHTML =
                    "âڑ ï¸ڈ ط£ط¯ط®ظ„ ط¬ظ…ظٹط¹ ط§ظ„ظ‚ظٹظ… ط§ظ„ظ…ط·ظ„ظˆط¨ط©";
                return;
            }

            if (V === 0) {
                result.innerHTML =
                    "â‌Œ ط§ظ„ط­ط¬ظ… ظ„ط§ ظٹظ…ظƒظ† ط£ظ† ظٹط³ط§ظˆظٹ طµظپط±ظ‹ط§";
                return;
            }

            answer = m / V;

            result.innerHTML =
                `âœ… دپ = ${answer.toFixed(6)} kg/mآ³`;

            return;
        }

        case "m": {

            const rho = getValue("Rho");
            const V = getValue("Volume");

            if (
                !Number.isFinite(rho) ||
                !Number.isFinite(V)
            ) {
                result.innerHTML =
                    "âڑ ï¸ڈ ط£ط¯ط®ظ„ ط¬ظ…ظٹط¹ ط§ظ„ظ‚ظٹظ… ط§ظ„ظ…ط·ظ„ظˆط¨ط©";
                return;
            }

            answer = rho * V;

            result.innerHTML =
                `âœ… m = ${answer.toFixed(6)} kg`;

            return;
        }

        case "V": {

            const rho = getValue("Rho");
            const m = getValue("Mass");

            if (
                !Number.isFinite(rho) ||
                !Number.isFinite(m)
            ) {
                result.innerHTML =
                    "âڑ ï¸ڈ ط£ط¯ط®ظ„ ط¬ظ…ظٹط¹ ط§ظ„ظ‚ظٹظ… ط§ظ„ظ…ط·ظ„ظˆط¨ط©";
                return;
            }

            if (rho === 0) {
                result.innerHTML =
                    "â‌Œ ط§ظ„ظƒط«ط§ظپط© ظ„ط§ ظٹظ…ظƒظ† ط£ظ† طھط³ط§ظˆظٹ طµظپط±ظ‹ط§";
                return;
            }

            answer = m / rho;

            result.innerHTML =
                `âœ… V = ${answer.toFixed(6)} mآ³`;

            return;
        }
    }
};
