// ًں§® ط­ط³ط§ط¨ Pâ‚‚ ظ…ظ† ظ…ط¹ط§ط¯ظ„ط© ط¨ط±ظ†ظˆظ„ظٹ
// ==========================================

window.calculatePhysicsBernoulli = function () {

    const result =
        document.getElementById(
            "physicsBernoulliResult"
        );

    if (!result) return;

    const getValue = id => {

        const element =
            document.getElementById(
                "physicsBernoulli" + id
            );

        return Number(element?.value);
    };

    const P1 = getValue("P1");
    const rho = getValue("Rho");
    const v1 = getValue("V1");
    const v2 = getValue("V2");
    const h1 = getValue("H1");
    const h2 = getValue("H2");

    if (
        !Number.isFinite(P1) ||
        !Number.isFinite(rho) ||
        !Number.isFinite(v1) ||
        !Number.isFinite(v2) ||
        !Number.isFinite(h1) ||
        !Number.isFinite(h2)
    ) {
        result.innerHTML =
            "âڑ ï¸ڈ ط£ط¯ط®ظ„ ط¬ظ…ظٹط¹ ط§ظ„ظ‚ظٹظ… ط§ظ„ظ…ط·ظ„ظˆط¨ط©";
        return;
    }

    if (rho <= 0) {
        result.innerHTML =
            "â‌Œ ط§ظ„ظƒط«ط§ظپط© ظٹط¬ط¨ ط£ظ† طھظƒظˆظ† ط£ظƒط¨ط± ظ…ظ† طµظپط±";
        return;
    }

    if (P1 < 0) {
        result.innerHTML =
            "â‌Œ ط§ظ„ط¶ط؛ط· ظ„ط§ ظٹظ…ظƒظ† ط£ظ† ظٹظƒظˆظ† ط³ط§ظ„ط¨ظ‹ط§";
        return;
    }

    const g = 9.80665;

    const P2 =
        P1
        + 0.5 * rho * (v1 ** 2 - v2 ** 2)
        + rho * g * (h1 - h2);

    result.innerHTML =
        `âœ… Pâ‚‚ = ${P2.toFixed(6)} Pa`;
};
