// ==========================================
// ًں§® ط­ط³ط§ط¨ ط§ظ„ط¶ط؛ط· ط§ظ„ط¬ظˆظٹ
// ==========================================

window.calculatePhysicsAtmosphericPressure = function () {

    const height =
        Number(
            document.getElementById(
                "physicsAtmosphericHeight"
            )?.value
        );

    const result =
        document.getElementById(
            "physicsAtmosphericResult"
        );

    if (!result) return;

    if (!Number.isFinite(height)) {

        result.innerHTML =
            "âڑ ï¸ڈ ط£ط¯ط®ظ„ ط§ظ„ط§ط±طھظپط§ط¹";

        return;
    }

    if (height < 0) {

        result.innerHTML =
            "â‌Œ ط§ظ„ط§ط±طھظپط§ط¹ ظ„ط§ ظٹظ…ظƒظ† ط£ظ† ظٹظƒظˆظ† ط³ط§ظ„ط¨ظ‹ط§";

        return;
    }

    // ط§ظ„ط«ظˆط§ط¨طھ
    const P0 = 101325;      // Pa
    const T0 = 288.15;      // K
    const L = 0.0065;       // K/m
    const g = 9.80665;      // m/sآ²
    const M = 0.0289644;    // kg/mol
    const R = 8.31447;      // J/(molآ·K)

    const temperatureFactor =
        1 - (L * height / T0);

    if (temperatureFactor <= 0) {

        result.innerHTML =
            "â‌Œ ط§ظ„ط§ط±طھظپط§ط¹ ط®ط§ط±ط¬ ظ†ط·ط§ظ‚ ظ‡ط°ظ‡ ط§ظ„ظ…ط¹ط§ط¯ظ„ط©";

        return;
    }

    const exponent =
        (g * M) / (R * L);

    const pressure =
        P0 *
        Math.pow(
            temperatureFactor,
            exponent
        );

    result.innerHTML =
        `âœ… P = ${pressure.toFixed(6)} Pa`;
};
