window.calculatePhysicsTotalFluidPressure = function () {

    const result =
        document.getElementById(
            "physicsTotalPressureResult"
        );

    if (!result) return;

    const getValue = id => {

        const element =
            document.getElementById(
                "physicsTotalPressure" + id
            );

        return Number(element?.value);
    };

    const Pa = getValue("Pa");
    const rho = getValue("Rho");
    const h = getValue("H");

    if (
        !Number.isFinite(Pa) ||
        !Number.isFinite(rho) ||
        !Number.isFinite(h)
    ) {
        result.innerHTML =
            "âڑ ï¸ڈ ط£ط¯ط®ظ„ ط¬ظ…ظٹط¹ ط§ظ„ظ‚ظٹظ… ط§ظ„ظ…ط·ظ„ظˆط¨ط©";
        return;
    }

    if (Pa < 0 || rho < 0 || h < 0) {
        result.innerHTML =
            "â‌Œ ط§ظ„ظ‚ظٹظ… ظ„ط§ ظٹظ…ظƒظ† ط£ظ† طھظƒظˆظ† ط³ط§ظ„ط¨ط©";
        return;
    }

    // ط«ط§ط¨طھ ط¹ط¬ظ„ط© ط§ظ„ط¬ط§ط°ط¨ظٹط©
    const g = 9.80665;

    const P =
        Pa + (rho * g * h);

    result.innerHTML =
        `âœ… P = ${P.toFixed(6)} Pa`;
};
