window.calculatePhysicsViscosity = function () {

    const F = Number(
        document.getElementById(
            "physicsViscosityForce"
        )?.value
    );

    const L = Number(
        document.getElementById(
            "physicsViscosityLength"
        )?.value
    );

    const A = Number(
        document.getElementById(
            "physicsViscosityArea"
        )?.value
    );

    const v = Number(
        document.getElementById(
            "physicsViscosityVelocity"
        )?.value
    );

    const result =
        document.getElementById(
            "physicsViscosityResult"
        );

    if (!result) return;

    if (
        !Number.isFinite(F) ||
        !Number.isFinite(L) ||
        !Number.isFinite(A) ||
        !Number.isFinite(v)
    ) {
        result.innerHTML =
            "âڑ ï¸ڈ ط£ط¯ط®ظ„ ط¬ظ…ظٹط¹ ط§ظ„ظ‚ظٹظ… ط§ظ„ظ…ط·ظ„ظˆط¨ط©";
        return;
    }

    if (F < 0 || L < 0 || A < 0 || v < 0) {
        result.innerHTML =
            "â‌Œ ط§ظ„ظ‚ظٹظ… ظ„ط§ ظٹظ…ظƒظ† ط£ظ† طھظƒظˆظ† ط³ط§ظ„ط¨ط©";
        return;
    }

    if (A === 0 || v === 0) {
        result.innerHTML =
            "â‌Œ ط§ظ„ظ…ط³ط§ط­ط© ظˆط§ظ„ط³ط±ط¹ط© ظٹط¬ط¨ ط£ظ† طھظƒظˆظ†ط§ ط£ظƒط¨ط± ظ…ظ† طµظپط±";
        return;
    }

    const eta =
        (F * L) / (A * v);

    result.innerHTML =
        `âœ… خ· = ${eta.toFixed(6)} Paآ·s`;
};
