window.calculatePhysicsStringFrequency = function () {

    const L = Number(
        document.getElementById(
            "physicsStringLength"
        )?.value
    );

    const T = Number(
        document.getElementById(
            "physicsStringTension"
        )?.value
    );

    const mu = Number(
        document.getElementById(
            "physicsStringLinearDensity"
        )?.value
    );

    const result =
        document.getElementById(
            "physicsStringFrequencyResult"
        );

    if (!result) return;

    if (
        !Number.isFinite(L) ||
        !Number.isFinite(T) ||
        !Number.isFinite(mu)
    ) {
        result.innerHTML =
            "âڑ ï¸ڈ ط£ط¯ط®ظ„ ط¬ظ…ظٹط¹ ط§ظ„ظ‚ظٹظ… ط§ظ„ظ…ط·ظ„ظˆط¨ط©";
        return;
    }

    if (L <= 0 || T < 0 || mu <= 0) {
        result.innerHTML =
            "â‌Œ ظٹط¬ط¨ ط£ظ† ظٹظƒظˆظ† ط·ظˆظ„ ط§ظ„ظˆطھط± ظˆط§ظ„ظƒط«ط§ظپط© ط§ظ„ط®ط·ظٹط© ط£ظƒط¨ط± ظ…ظ† طµظپط±طŒ ظˆط§ظ„ط´ط¯ ط؛ظٹط± ط³ط§ظ„ط¨";
        return;
    }

    const f =
        (1 / (2 * L)) *
        Math.sqrt(T / mu);

    result.innerHTML =
        `âœ… f = ${f.toFixed(6)} Hz`;
};
