// ==========================================
// ًں§® ط­ط³ط§ط¨ طھط£ط«ظٹط± ط¯ظˆط¨ظ„ط±
// ==========================================

window.calculatePhysicsDopplerEffect = function () {

    const f = Number(
        document.getElementById(
            "physicsDopplerFrequency"
        )?.value
    );

    const v = Number(
        document.getElementById(
            "physicsDopplerSoundSpeed"
        )?.value
    );

    const vo = Number(
        document.getElementById(
            "physicsDopplerObserverSpeed"
        )?.value
    );

    const vs = Number(
        document.getElementById(
            "physicsDopplerSourceSpeed"
        )?.value
    );

    const direction =
        document.getElementById(
            "physicsDopplerDirection"
        )?.value;

    const result =
        document.getElementById(
            "physicsDopplerResult"
        );

    if (!result) return;

    if (
        !Number.isFinite(f) ||
        !Number.isFinite(v) ||
        !Number.isFinite(vo) ||
        !Number.isFinite(vs)
    ) {
        result.innerHTML =
            "âڑ ï¸ڈ ط£ط¯ط®ظ„ ط¬ظ…ظٹط¹ ط§ظ„ظ‚ظٹظ… ط§ظ„ظ…ط·ظ„ظˆط¨ط©";
        return;
    }

    if (f <= 0 || v <= 0 || vo < 0 || vs < 0) {
        result.innerHTML =
            "â‌Œ طھط£ظƒط¯ ظ…ظ† ط£ظ† ط§ظ„ظ‚ظٹظ… ط§ظ„ظ…ط¯ط®ظ„ط© طµط­ظٹط­ط©";
        return;
    }

    let observedFrequency;

    if (direction === "approaching") {

        // ط§ظ‚طھط±ط§ط¨:
        // ط§ظ„ط¨ط³ط· ظٹط²ظٹط¯ ظˆط§ظ„ظ…ظ‚ط§ظ… ظٹظ‚ظ„

        if (vs >= v) {
            result.innerHTML =
                "â‌Œ ط³ط±ط¹ط© ط§ظ„ظ…طµط¯ط± ظٹط¬ط¨ ط£ظ† طھظƒظˆظ† ط£ظ‚ظ„ ظ…ظ† ط³ط±ط¹ط© ط§ظ„طµظˆطھ";
            return;
        }

        observedFrequency =
            f * (v + vo) / (v - vs);

    } else {

        // ط§ط¨طھط¹ط§ط¯:
        // ط§ظ„ط¨ط³ط· ظٹظ‚ظ„ ظˆط§ظ„ظ…ظ‚ط§ظ… ظٹط²ظٹط¯

        observedFrequency =
            f * (v - vo) / (v + vs);

        if (v - vo <= 0) {
            result.innerHTML =
                "â‌Œ ط³ط±ط¹ط© ط§ظ„ظ…ط±ط§ظ‚ط¨ ظٹط¬ط¨ ط£ظ† طھظƒظˆظ† ط£ظ‚ظ„ ظ…ظ† ط³ط±ط¹ط© ط§ظ„طµظˆطھ";
            return;
        }
    }

    result.innerHTML =
        `âœ… fâ€² = ${observedFrequency.toFixed(6)} Hz`;
};
