window.calculatePhysicsMagneticForce = function () {

    const B = Number(
        document.getElementById(
            "physicsMagneticB"
        )?.value
    );

    const I = Number(
        document.getElementById(
            "physicsMagneticI"
        )?.value
    );

    const L = Number(
        document.getElementById(
            "physicsMagneticL"
        )?.value
    );

    const theta = Number(
        document.getElementById(
            "physicsMagneticTheta"
        )?.value
    );

    const result =
        document.getElementById(
            "physicsMagneticForceResult"
        );

    if (!result) return;

    if (
        !Number.isFinite(B) ||
        !Number.isFinite(I) ||
        !Number.isFinite(L) ||
        !Number.isFinite(theta)
    ) {
        result.innerHTML =
            "âڑ ï¸ڈ ط£ط¯ط®ظ„ ط¬ظ…ظٹط¹ ط§ظ„ظ‚ظٹظ… ط§ظ„ظ…ط·ظ„ظˆط¨ط©";
        return;
    }

    if (B < 0 || I < 0 || L < 0) {
        result.innerHTML =
            "â‌Œ B ظˆ I ظˆ L ظ„ط§ ظٹظ…ظƒظ† ط£ظ† طھظƒظˆظ† ط³ط§ظ„ط¨ط©";
        return;
    }

    if (theta < 0 || theta > 180) {
        result.innerHTML =
            "â‌Œ ط§ظ„ط²ط§ظˆظٹط© ظٹط¬ط¨ ط£ظ† طھظƒظˆظ† ط¨ظٹظ† 0آ° ظˆ 180آ°";
        return;
    }

    const thetaRad =
        theta * Math.PI / 180;

    const F =
        B * I * L * Math.sin(thetaRad);

    result.innerHTML =
        `âœ… F = ${F.toFixed(6)} N`;
};
