window.calculatePhysicsMagneticFlux = function () {

    const B = Number(
        document.getElementById(
            "physicsFluxB"
        )?.value
    );

    const A = Number(
        document.getElementById(
            "physicsFluxArea"
        )?.value
    );

    const theta = Number(
        document.getElementById(
            "physicsFluxTheta"
        )?.value
    );

    const result =
        document.getElementById(
            "physicsFluxResult"
        );

    if (!result) return;

    if (
        !Number.isFinite(B) ||
        !Number.isFinite(A) ||
        !Number.isFinite(theta)
    ) {
        result.innerHTML =
            "âڑ ï¸ڈ ط£ط¯ط®ظ„ ط¬ظ…ظٹط¹ ط§ظ„ظ‚ظٹظ… ط§ظ„ظ…ط·ظ„ظˆط¨ط©";
        return;
    }

    if (B < 0) {
        result.innerHTML =
            "â‌Œ ط§ظ„ظ…ط¬ط§ظ„ ط§ظ„ظ…ط؛ظ†ط§ط·ظٹط³ظٹ ظ„ط§ ظٹظ…ظƒظ† ط£ظ† ظٹظƒظˆظ† ط³ط§ظ„ط¨ظ‹ط§";
        return;
    }

    if (A < 0) {
        result.innerHTML =
            "â‌Œ ط§ظ„ظ…ط³ط§ط­ط© ظ„ط§ ظٹظ…ظƒظ† ط£ظ† طھظƒظˆظ† ط³ط§ظ„ط¨ط©";
        return;
    }

    if (theta < 0 || theta > 180) {
        result.innerHTML =
            "â‌Œ ط§ظ„ط²ط§ظˆظٹط© ظٹط¬ط¨ ط£ظ† طھظƒظˆظ† ط¨ظٹظ† 0آ° ظˆ 180آ°";
        return;
    }

    const thetaRad =
        theta * Math.PI / 180;

    const flux =
        B * A * Math.cos(thetaRad);

    result.innerHTML =
        `âœ… خ¦ = ${flux.toFixed(6)} Wb`;
};
