window.calculatePhysicsMagneticDipoleTorque = function () {

    const N = Number(
        document.getElementById(
            "physicsTorqueN"
        )?.value
    );

    const I = Number(
        document.getElementById(
            "physicsTorqueI"
        )?.value
    );

    const A = Number(
        document.getElementById(
            "physicsTorqueArea"
        )?.value
    );

    const B = Number(
        document.getElementById(
            "physicsTorqueB"
        )?.value
    );

    const theta = Number(
        document.getElementById(
            "physicsTorqueTheta"
        )?.value
    );

    const result =
        document.getElementById(
            "physicsTorqueResult"
        );

    if (!result) return;

    if (
        !Number.isFinite(N) ||
        !Number.isFinite(I) ||
        !Number.isFinite(A) ||
        !Number.isFinite(B) ||
        !Number.isFinite(theta)
    ) {
        result.innerHTML =
            "âڑ ï¸ڈ ط£ط¯ط®ظ„ ط¬ظ…ظٹط¹ ط§ظ„ظ‚ظٹظ… ط§ظ„ظ…ط·ظ„ظˆط¨ط©";
        return;
    }

    if (N <= 0) {
        result.innerHTML =
            "â‌Œ ط¹ط¯ط¯ ط§ظ„ظ„ظپط§طھ ظٹط¬ط¨ ط£ظ† ظٹظƒظˆظ† ط£ظƒط¨ط± ظ…ظ† طµظپط±";
        return;
    }

    if (I < 0 || A < 0 || B < 0) {
        result.innerHTML =
            "â‌Œ I ظˆ A ظˆ B ظ„ط§ ظٹظ…ظƒظ† ط£ظ† طھظƒظˆظ† ط³ط§ظ„ط¨ط©";
        return;
    }

    if (theta < 0 || theta > 180) {
        result.innerHTML =
            "â‌Œ ط§ظ„ط²ط§ظˆظٹط© ظٹط¬ط¨ ط£ظ† طھظƒظˆظ† ط¨ظٹظ† 0آ° ظˆ 180آ°";
        return;
    }

    const thetaRad =
        theta * Math.PI / 180;

    const torque =
        N * I * A * B *
        Math.sin(thetaRad);

    result.innerHTML =
        `âœ… د„ = ${torque.toFixed(6)} Nآ·m`;
};
