// ًں§® ط­ط³ط§ط¨ طھط£ط«ظٹط± ظƒظˆظ…ط¨طھظˆظ†
// ==========================================

window.calculatePhysicsComptonEffect = function () {

    const lambda = Number(
        document.getElementById(
            "physicsComptonLambda"
        )?.value
    );

    const theta = Number(
        document.getElementById(
            "physicsComptonTheta"
        )?.value
    );

    const result =
        document.getElementById(
            "physicsComptonResult"
        );

    if (!result) return;

    if (
        !Number.isFinite(lambda) ||
        !Number.isFinite(theta)
    ) {
        result.innerHTML =
            "âڑ ï¸ڈ ط£ط¯ط®ظ„ ط¬ظ…ظٹط¹ ط§ظ„ظ‚ظٹظ… ط§ظ„ظ…ط·ظ„ظˆط¨ط©";
        return;
    }

    if (lambda < 0) {
        result.innerHTML =
            "â‌Œ ط§ظ„ط·ظˆظ„ ط§ظ„ظ…ظˆط¬ظٹ ظ„ط§ ظٹظ…ظƒظ† ط£ظ† ظٹظƒظˆظ† ط³ط§ظ„ط¨ظ‹ط§";
        return;
    }

    if (theta < 0 || theta > 180) {
        result.innerHTML =
            "â‌Œ ط§ظ„ط²ط§ظˆظٹط© ظٹط¬ط¨ ط£ظ† طھظƒظˆظ† ط¨ظٹظ† 0آ° ظˆ 180آ°";
        return;
    }

    const h =
        6.62607015e-34;

    const me =
        9.1093837139e-31;

    const c =
        299792458;

    const thetaRad =
        theta * Math.PI / 180;

    const comptonWavelength =
        h / (me * c);

    const deltaLambda =
        comptonWavelength *
        (1 - Math.cos(thetaRad));

    const lambdaPrime =
        lambda + deltaLambda;

    result.innerHTML =
        `âœ… خ»â€² = ${lambdaPrime.toExponential(6)} m`;
};
