window.calculatePhysicsHalfLife = function () {

    const N0 = Number(
        document.getElementById(
            "physicsHalfLifeInitial"
        )?.value
    );

    const N = Number(
        document.getElementById(
            "physicsHalfLifeRemaining"
        )?.value
    );

    const t = Number(
        document.getElementById(
            "physicsHalfLifeTime"
        )?.value
    );

    const result =
        document.getElementById(
            "physicsHalfLifeResult"
        );

    if (!result) return;

    if (
        !Number.isFinite(N0) ||
        !Number.isFinite(N) ||
        !Number.isFinite(t)
    ) {
        result.innerHTML =
            "âڑ ï¸ڈ ط£ط¯ط®ظ„ ط¬ظ…ظٹط¹ ط§ظ„ظ‚ظٹظ… ط§ظ„ظ…ط·ظ„ظˆط¨ط©";
        return;
    }

    if (N0 <= 0) {
        result.innerHTML =
            "â‌Œ Nâ‚€ ظٹط¬ط¨ ط£ظ† ظٹظƒظˆظ† ط£ظƒط¨ط± ظ…ظ† طµظپط±";
        return;
    }

    if (N <= 0 || N >= N0) {
        result.innerHTML =
            "â‌Œ ظٹط¬ط¨ ط£ظ† ظٹظƒظˆظ† 0 < N < Nâ‚€";
        return;
    }

    if (t < 0) {
        result.innerHTML =
            "â‌Œ ط§ظ„ط²ظ…ظ† ظ„ط§ ظٹظ…ظƒظ† ط£ظ† ظٹظƒظˆظ† ط³ط§ظ„ط¨ظ‹ط§";
        return;
    }

    const halfLife =
        (t * Math.log(2)) /
        Math.log(N0 / N);

    result.innerHTML =
        `âœ… Tآ½ = ${halfLife.toFixed(6)} s`;
};
