// ==========================================
// ًں§® ط­ط³ط§ط¨ ط§ظ„طھط­ظˆظٹظ„
// ==========================================

window.calculateTemperatureConversion = function (type) {

    const input = document.getElementById("temperatureConversionInput");
    const result = document.getElementById("temperatureConversionResult");

    if (!input || !result) return;

    const value = Number(input.value);

    if (input.value === "" || !Number.isFinite(value)) {
        result.innerHTML = "âڑ ï¸ڈ ط£ط¯ط®ظ„ ظ‚ظٹظ…ط© طµط­ظٹط­ط©";
        return;
    }

    let answer;
    let unit;

    switch (type) {

        case "CtoF":
            answer = (value * 9 / 5) + 32;
            unit = "آ°F";
            break;

        case "FtoC":
            answer = (value - 32) * 5 / 9;
            unit = "آ°C";
            break;

        case "CtoK":
            answer = value + 273.15;
            unit = "K";
            break;

        case "KtoC":
            answer = value - 273.15;
            unit = "آ°C";
            break;

        case "FtoK":
            answer = (value - 32) * 5 / 9 + 273.15;
            unit = "K";
            break;

        case "KtoF":
            answer = (value - 273.15) * 9 / 5 + 32;
            unit = "آ°F";
            break;

        default:
            result.innerHTML = "âڑ ï¸ڈ ظ†ظˆط¹ طھط­ظˆظٹظ„ ط؛ظٹط± ظ…ط¹ط±ظˆظپ";
            return;
    }

    result.innerHTML = `âœ… ${answer.toFixed(6)} ${unit}`;
};

