window.matrixDetA = function () {

    if (!window.matrices || !window.matrices.A) {
        return;
    }

    const A = window.matrices.A;
    const form = document.getElementById("matrixForm");

    if (!form) return;

    if (A.length !== A[0].length) {

        form.innerHTML = `
            <div style="
                font-size:13px;
                font-weight:bold;
                text-align:center;
            ">
                Det requires square matrix
            </div>
        `;

        return;
    }

    function determinant(M) {

        const n = M.length;

        if (n === 1) {
            return M[0][0];
        }

        if (n === 2) {
            return (
                M[0][0] * M[1][1] -
                M[0][1] * M[1][0]
            );
        }

        let det = 0;

        for (let col = 0; col < n; col++) {

            const minor = M
                .slice(1)
                .map(row =>
                    row.filter((_, j) => j !== col)
                );

            det +=
                (col % 2 === 0 ? 1 : -1) *
                M[0][col] *
                determinant(minor);
        }

        return det;
    }

    const det = determinant(A);

    form.innerHTML = `
        <div style="
            font-size:13px;
            font-weight:bold;
            text-align:center;
        ">
            Det(MatA) = ${Number(det.toFixed(10))}
        </div>
    `;
};
window.matrixRankA = function () {

    if (!window.matrices || !window.matrices.A) {
        return;
    }

    const A = window.matrices.A;
    const form = document.getElementById("matrixForm");

    if (!form) return;

    const M = A.map(row => row.map(Number));

    let rank = 0;
    let row = 0;

    const rows = M.length;
    const cols = M[0].length;

    for (let col = 0; col < cols && row < rows; col++) {

        let pivot = row;

        for (let i = row + 1; i < rows; i++) {

            if (
                Math.abs(M[i][col]) >
                Math.abs(M[pivot][col])
            ) {
                pivot = i;
            }
        }

        if (Math.abs(M[pivot][col]) < 1e-10) {
            continue;
        }

        [M[row], M[pivot]] =
            [M[pivot], M[row]];

        for (let i = row + 1; i < rows; i++) {

            const factor =
                M[i][col] / M[row][col];

            for (let j = col; j < cols; j++) {

                M[i][j] -=
                    factor * M[row][j];
            }
        }

        rank++;
        row++;
    }

    form.innerHTML = `
        <div style="
            font-size:13px;
            font-weight:bold;
            text-align:center;
        ">
            Rank(MatA) = ${rank}
        </div>
    `;
};
