window.matrixNormA = function () {

    if (!window.matrices || !window.matrices.A) {
        return;
    }

    const A = window.matrices.A;
    const form = document.getElementById("matrixForm");

    if (!form) return;

    let sum = 0;

    for (let i = 0; i < A.length; i++) {

        for (let j = 0; j < A[i].length; j++) {

            sum += Number(A[i][j]) ** 2;

        }
    }

    const norm = Math.sqrt(sum);

    form.innerHTML = `
        <div style="
            font-size:13px;
            font-weight:bold;
            text-align:center;
        ">
            Norm(MatA) = ${Number(norm.toFixed(10))}
        </div>
    `;
};
window.matrixCondA = function () {

    if (!window.matrices || !window.matrices.A) return;

    const A = window.matrices.A;
    const form = document.getElementById("matrixForm");

    if (!form) return;

    const n = A.length;

    if (n === 0 || n !== A[0].length) {
        form.innerHTML = `
            <div style="font-size:13px;font-weight:bold;text-align:center;">
                Cond(MatA) requires square matrix
            </div>
        `;
        return;
    }

    // ==========================================
    // ظ†ط³ط® A
    // ==========================================

    const M = A.map(row => row.map(Number));

    const I = M.map((row, i) =>
        row.map((_, j) => i === j ? 1 : 0)
    );

    // ==========================================
    // Gauss-Jordan ظ„ط­ط³ط§ط¨ Aâپ»آ¹
    // ==========================================

    for (let col = 0; col < n; col++) {

        let pivot = col;

        for (let r = col + 1; r < n; r++) {

            if (
                Math.abs(M[r][col]) >
                Math.abs(M[pivot][col])
            ) {
                pivot = r;
            }
        }

        if (Math.abs(M[pivot][col]) < 1e-12) {

            form.innerHTML = `
                <div style="font-size:13px;font-weight:bold;text-align:center;">
                    Cond(MatA) = âˆ‍
                </div>
            `;

            return;
        }

        [M[col], M[pivot]] =
            [M[pivot], M[col]];

        [I[col], I[pivot]] =
            [I[pivot], I[col]];

        const p = M[col][col];

        for (let j = 0; j < n; j++) {
            M[col][j] /= p;
            I[col][j] /= p;
        }

        for (let r = 0; r < n; r++) {

            if (r === col) continue;

            const factor = M[r][col];

            for (let j = 0; j < n; j++) {

                M[r][j] -=
                    factor * M[col][j];

                I[r][j] -=
                    factor * I[col][j];
            }
        }
    }

    // ==========================================
    // Frobenius Norm
    // ==========================================

    function frobeniusNorm(X) {

        let sum = 0;

        for (let i = 0; i < X.length; i++) {

            for (let j = 0; j < X[i].length; j++) {

                const v = Number(X[i][j]);

                sum += v * v;
            }
        }

        return Math.sqrt(sum);
    }

    const normA = frobeniusNorm(A);
    const normInv = frobeniusNorm(I);

    const cond = normA * normInv;

    form.innerHTML = `
        <div style="
            font-size:13px;
            font-weight:bold;
            text-align:center;
        ">
            Cond(MatA) = ${cond.toFixed(6)}
        </div>
    `;
};
window.matrixDetA = function () {

    if (!window.matrices || !window.matrices.A) return;

    const A = window.matrices.A;
    const form = document.getElementById("matrixForm");

    if (!form) return;

    const n = A.length;

    if (n === 0 || n !== A[0].length) {
        form.innerHTML = `
            <div style="font-size:13px;font-weight:bold;text-align:center;">
                Det(MatA) requires square matrix
            </div>
        `;
        return;
    }

    // ==========================================
    // ظ†ط³ط® ط§ظ„ظ…طµظپظˆظپط©
    // ==========================================

    const M = A.map(row => row.map(Number));

    let det = 1;

    // ==========================================
    // Gaussian Elimination
    // ==========================================

    for (let col = 0; col < n; col++) {

        let pivot = col;

        for (let r = col + 1; r < n; r++) {

            if (
                Math.abs(M[r][col]) >
                Math.abs(M[pivot][col])
            ) {
                pivot = r;
            }
        }

        // ط§ظ„ظ…طµظپظˆظپط© ظ…ظپط±ط¯ط©
        if (Math.abs(M[pivot][col]) < 1e-12) {

            det = 0;
            break;
        }

        // طھط¨ط¯ظٹظ„ ط§ظ„طµظپظˆظپ
        if (pivot !== col) {
            [M[col], M[pivot]] =
    [M[pivot], M[col]];

            det *= -1;
        }

        const p = M[col][col];

        det *= p;

        // طھطµظپظٹط± ط§ظ„ط¹ظ†ط§طµط± طھط­طھ ط§ظ„ظ€ pivot
        for (let r = col + 1; r < n; r++) {

            const factor = M[r][col] / p;

            for (let j = col; j < n; j++) {

                M[r][j] -=
                    factor * M[col][j];
            }
        }
    }

    // ==========================================
    // ط¹ط±ط¶ ط§ظ„ظ†طھظٹط¬ط©
    // ==========================================

    form.innerHTML = `
        <div style="
            font-size:13px;
            font-weight:bold;
            text-align:center;
        ">
            Det(MatA) = ${det.toFixed(6)}
        </div>
    `;
};
