function solveLinearFromValues() {

    const values = eqnData.values;

    if (values.length !== 6) return;

    const a1 = values[0];
    const b1 = values[1];
    const c1 = values[2];

    const a2 = values[3];
    const b2 = values[4];
    const c2 = values[5];

    const resDiv = document.getElementById("eqnResult");

    if (!resDiv) return;

    const D = a1 * b2 - a2 * b1;

    if (D === 0) {

        resDiv.innerHTML = "ظ„ط§ ظٹظˆط¬ط¯ ط­ظ„ ظپط±ظٹط¯";

        return;
    }

    const x = (c1 * b2 - c2 * b1) / D;
    const y = (a1 * c2 - a2 * c1) / D;

    resDiv.innerHTML =
        `X = ${x.toFixed(4)}<br>` +
        `Y = ${y.toFixed(4)}`;
}
function solveQuadFromValues() {

    const values = eqnData.values;

    if (values.length !== 3) return;

    const a = values[0];
    const b = values[1];
    const c = values[2];

    const resDiv = document.getElementById("eqnResult");

    if (!resDiv) return;

    if (a === 0) {
        resDiv.innerHTML = "ط®ط·ط£: a ظ„ط§ طھط³ط§ظˆظٹ 0";
        return;
    }

    const d = b * b - 4 * a * c;

    if (d > 0) {

        const x1 = (-b + Math.sqrt(d)) / (2 * a);
        const x2 = (-b - Math.sqrt(d)) / (2 * a);

        resDiv.innerHTML =
            `X1 = ${x1.toFixed(4)}<br>` +
            `X2 = ${x2.toFixed(4)}`;

    } else if (d === 0) {

        const x = -b / (2 * a);

        resDiv.innerHTML =
            `X1 = X2 = ${x.toFixed(4)}`;

    } else {

        const real = -b / (2 * a);
        const imag = Math.sqrt(-d) / (2 * a);

        resDiv.innerHTML =
            `X1 = ${real.toFixed(4)} + ${imag.toFixed(4)}i<br>` +
            `X2 = ${real.toFixed(4)} - ${imag.toFixed(4)}i`;
    }
}
