// ط§ظ„ظ…ط¹ط§ط¯ظ„ط§طھ ط§ظ„ط®ط·ظٹط©
// ==========================================

window.solveLin = function() {

    let a1 = Number(document.getElementById("ea1").value);
    let b1 = Number(document.getElementById("eb1").value);
    let c1 = Number(document.getElementById("ec1").value);

    let a2 = Number(document.getElementById("ea2").value);
    let b2 = Number(document.getElementById("eb2").value);
    let c2 = Number(document.getElementById("ec2").value);

    let resDiv = document.getElementById("eqnResult");

    let D = a1 * b2 - a2 * b1;

    if (D === 0) {

        resDiv.innerHTML = "ظ„ط§ ظٹظˆط¬ط¯ ط­ظ„ ظپط±ظٹط¯";

    } else {

        let x = (c1 * b2 - c2 * b1) / D;
        let y = (a1 * c2 - a2 * c1) / D;

        resDiv.innerHTML =
            `X = ${x.toFixed(4)}<br>` +
            `Y = ${y.toFixed(4)}`;
    }
};


// ==========================================
// ط­ظ„ ط§ظ„ط¯ط±ط¬ط© ط§ظ„ط±ط§ط¨ط¹ط©
// axâپ´ + bxآ³ + cxآ² + dx + e = 0
// ==========================================

window.solveQuarticFromValues = function() {

    const values = quarticData.values;

    if (values.length !== 5) return;

    const a = values[0];
    const b = values[1];
    const c = values[2];
    const d = values[3];
    const e = values[4];

    const resDiv = document.getElementById("eqnResult");

    if (!resDiv) return;

    if (a === 0) {
        resDiv.innerHTML = "ط®ط·ط£: a ظ„ط§ طھط³ط§ظˆظٹ 0";
        return;
    }

    // ==========================================
    // طھط­ظˆظٹظ„ ط§ظ„ظ…ط¹ط§ط¯ظ„ط© ط¥ظ„ظ‰ ط§ظ„طµظˆط±ط©:
    // xâپ´ + A xآ³ + B xآ² + C x + D = 0
    // ==========================================

    const A = b / a;
    const B = c / a;
    const C = d / a;
    const D = e / a;

    // ==========================================
    // ظ†ط­ظˆظ„ظ‡ط§ ط¥ظ„ظ‰:
    // yâپ´ + p yآ² + q y + r = 0
    // ==========================================

    const p = B - (3 * A * A) / 8;

    const q =
        C -
        (A * B) / 2 +
        (A * A * A) / 8;

    const r =
        D -
        (A * C) / 4 +
        (A * A * B) / 16 -
        (3 * A * A * A * A) / 256;

    const EPS = 1e-10;

    // ==========================================
    // ط­ط§ظ„ط© q = 0
    // ط§ظ„ظ…ط¹ط§ط¯ظ„ط© طھطµط¨ط­:
    // yâپ´ + p yآ² + r = 0
    // ==========================================

    if (Math.abs(q) < EPS) {

        const roots = [];

        const disc = p * p - 4 * r;

        if (disc >= -EPS) {

            const sqrtDisc = Math.sqrt(Math.max(0, disc));

            const y1sq = (-p + sqrtDisc) / 2;
            const y2sq = (-p - sqrtDisc) / 2;

            if (y1sq >= -EPS) {

                const s = Math.sqrt(Math.max(0, y1sq));

                roots.push(
                    -A / 4 + s,
                    -A / 4 - s
                );
            }

            if (y2sq >= -EPS) {

                const s = Math.sqrt(Math.max(0, y2sq));

                roots.push(
                    -A / 4 + s,
                    -A / 4 - s
                );
            }

        } else {

            const realY2 = -p / 2;
            const imagY2 = Math.sqrt(-disc) / 2;

            const realS = Math.sqrt(
                (Math.sqrt(realY2 * realY2 + imagY2 * imagY2) + realY2) / 2
            );

            const imagS =
                imagY2 / (2 * realS);

            roots.push(
                `${(-A / 4 + realS).toFixed(6)} + ${imagS.toFixed(6)}i`,
                `${(-A / 4 + realS).toFixed(6)} - ${imagS.toFixed(6)}i`,
                `${(-A / 4 - realS).toFixed(6)} + ${imagS.toFixed(6)}i`,
                `${(-A / 4 - realS).toFixed(6)} - ${imagS.toFixed(6)}i`
            );
        }

        resDiv.innerHTML = roots
            .map((x, i) =>
                `X${i + 1} = ${
                    typeof x === "number"
                        ? x.toFixed(6)
                        : x
                }`
            )
            .join("<br>");

        return;
    }

    // ==========================================
    // ط­ظ„ ط§ظ„ظ…ط¹ط§ط¯ظ„ط© ط§ظ„ظ…ظƒط¹ط¨ط© ط§ظ„ظ…ط³ط§ط¹ط¯ط©
    // ==========================================

    const cubicA = -p / 2;
    const cubicB = -r;
    const cubicC = r * p / 2 - q * q / 8;

    const cubicRoots = solveCubicNumerically(
        1,
        cubicA,
        cubicC,
        cubicB
    );

    // ظ†ط­طھط§ط¬ ط¬ط°ط±ظ‹ط§ ط­ظ‚ظٹظ‚ظٹظ‹ط§ ظ…ظ†ط§ط³ط¨ظ‹ط§
    let z = null;

    for (const root of cubicRoots) {

        if (
            typeof root === "number" &&
            Number.isFinite(root) &&
            root >= -EPS
        ) {
            z = root;
            break;
        }
    }

    if (z === null) {
        resDiv.innerHTML = "طھط¹ط°ط± ط­ظ„ ط§ظ„ظ…ط¹ط§ط¯ظ„ط©";
        return;
    }

    const alpha = Math.sqrt(Math.max(0, 2 * z - p));

    if (Math.abs(alpha) < EPS) {
        resDiv.innerHTML = "طھط¹ط°ط± ط­ظ„ ط§ظ„ظ…ط¹ط§ط¯ظ„ط©";
        return;
    }

    const beta = q / (2 * alpha);

    const disc1 =
        -(2 * z + p + 2 * beta);

    const disc2 =
        -(2 * z + p - 2 * beta);

    const roots = [];

    // ==========================================
    // ط§ظ„ط¬ط°ط± ط§ظ„ط£ظˆظ„ ظˆط§ظ„ط«ط§ظ†ظٹ
    // ==========================================

    if (disc1 >= -EPS) {

        const s = Math.sqrt(Math.max(0, disc1));

        roots.push(
            -A / 4 + (alpha + s) / 2,
            -A / 4 + (alpha - s) / 2
        );

    } else {

        const s = Math.sqrt(-disc1);

        roots.push(
            {
                re: -A / 4 + alpha / 2,
                im: s / 2
            },
            {
                re: -A / 4 + alpha / 2,
                im: -s / 2
            }
        );
    }

    // ==========================================
    // ط§ظ„ط¬ط°ط± ط§ظ„ط«ط§ظ„ط« ظˆط§ظ„ط±ط§ط¨ط¹
    // ==========================================

    if (disc2 >= -EPS) {

        const s = Math.sqrt(Math.max(0, disc2));

        roots.push(
            -A / 4 + (-alpha + s) / 2,
            -A / 4 + (-alpha - s) / 2
        );

    } else {

        const s = Math.sqrt(-disc2);

        roots.push(
            {
                re: -A / 4 - alpha / 2,
                im: s / 2
            },
            {
                re: -A / 4 - alpha / 2,
                im: -s / 2
            }
        );
    }

    // ==========================================
    // طھظ†ط³ظٹظ‚ ط§ظ„ظ†طھط§ط¦ط¬
    // ==========================================

    resDiv.innerHTML = roots
        .map((root, i) => {

            if (typeof root === "number") {

                const clean =
                    Math.abs(root) < 1e-8
                        ? 0
                        : root;

                return `X${i + 1} = ${clean.toFixed(6)}`;
            }

            const re =
                Math.abs(root.re) < 1e-8
                    ? 0
                    : root.re;

            const im =
                Math.abs(root.im) < 1e-8
                    ? 0
                    : root.im;

            const sign = im >= 0 ? "+" : "-";

            return `X${i + 1} = ${re.toFixed(6)} ${sign} ${Math.abs(im).toFixed(6)}i`;
        })
        .join("<br>");
};


