// ظ…ط³ط§ط¹ط¯ ط­ظ„ ط§ظ„ظ…ط¹ط§ط¯ظ„ط© ط§ظ„طھظƒط¹ظٹط¨ظٹط©
// ==========================================

function solveCubicNumerically(a, b, c, d) {

    const A = b / a;
    const B = c / a;
    const C = d / a;

    const p = B - A * A / 3;

    const q =
        2 * A * A * A / 27 -
        A * B / 3 +
        C;

    const delta =
        q * q / 4 +
        p * p * p / 27;

    const roots = [];

    if (delta > 1e-12) {

        const sqrtDelta = Math.sqrt(delta);

        const u = Math.cbrt(-q / 2 + sqrtDelta);
        const v = Math.cbrt(-q / 2 - sqrtDelta);

        roots.push(
            u + v - A / 3
        );

    } else if (Math.abs(delta) <= 1e-12) {

        const u = Math.cbrt(-q / 2);

        roots.push(
            2 * u - A / 3,
            -u - A / 3
        );

    } else {

        const r =
            2 * Math.sqrt(-p / 3);

        let cosValue =
            (3 * q / (2 * p)) *
            Math.sqrt(-3 / p);

        cosValue =
            Math.max(
                -1,
                Math.min(1, cosValue)
            );

        const theta =
            Math.acos(cosValue);

        roots.push(
            r * Math.cos(theta / 3) - A / 3,
            r * Math.cos((theta + 2 * Math.PI) / 3) - A / 3,
            r * Math.cos((theta + 4 * Math.PI) / 3) - A / 3
        );
    }

    return roots;
}
