window.calcRegression = function() {
    const xInput = document.getElementById("statXInput");
    const yInput = document.getElementById("statYInput");
    const result = document.getElementById("regRes");

    const x = xInput.value
        .trim()
        .split(",")
        .map(v => Number(v.trim()))
        .filter(v => Number.isFinite(v));

    const y = yInput.value
        .trim()
        .split(",")
        .map(v => Number(v.trim()))
        .filter(v => Number.isFinite(v));

    if (x.length < 2 || y.length < 2) {
        result.innerHTML = "ط£ط¯ط®ظ„ X ظˆ Y";
        return;
    }

    if (x.length !== y.length) {
        result.innerHTML =
            `ط¹ط¯ط¯ X = ${x.length}<br>ط¹ط¯ط¯ Y = ${y.length}`;
        return;
    }

    const n = x.length;

    const sumX = x.reduce((a,b) => a+b, 0);
    const sumY = y.reduce((a,b) => a+b, 0);

    const sumXY = x.reduce((s,xi,i) => s + xi*y[i], 0);
    const sumX2 = x.reduce((s,xi) => s + xi*xi, 0);

    const denominator = n * sumX2 - sumX * sumX;

    if (denominator === 0) {
        result.innerHTML = "ظ„ط§ ظٹظ…ظƒظ† ط­ط³ط§ط¨ ط§ظ„ط§ظ†ط­ط¯ط§ط±";
        return;
    }

    const b =
        (n * sumXY - sumX * sumY) / denominator;

    const a =
        (sumY - b * sumX) / n;

    // ط­ظپط¸ ظ…ط¹ط§ط¯ظ„ط© ط§ظ„ط§ظ†ط­ط¯ط§ط±
    regressionA = a;
    regressionB = b;

    const meanY = sumY / n;

    const ssTot = y.reduce(
        (s,yi) => s + Math.pow(yi - meanY, 2),
        0
    );

    const ssRes = y.reduce(
        (s,yi,i) =>
            s + Math.pow(yi - (a + b*x[i]), 2),
        0
    );

    const r2 =
        ssTot === 0 ? 1 : 1 - ssRes / ssTot;

    const r = Math.sqrt(Math.max(0, r2));

    result.innerHTML = `
        a = ${a.toFixed(6)}<br>
        b = ${b.toFixed(6)}<br>
        y = ${a.toFixed(6)} + ${b.toFixed(6)}x<br>
        R = ${r.toFixed(6)}<br>
        Rآ² = ${r2.toFixed(6)}
    `;
};
window.predictRegression = function() {
    const input = document.getElementById("predictX");
    const result = document.getElementById("regRes");

    const x = Number(input.value);

    if (!Number.isFinite(x)) {
        result.innerHTML = "ط£ط¯ط®ظ„ ظ‚ظٹظ…ط© X طµط­ظٹط­ط©";
        return;
    }

    if (regressionA === null || regressionB === null) {
        result.innerHTML = "ط§ط­ط³ط¨ REG ط£ظˆظ„ظ‹ط§";
        return;
    }

    const y = regressionA + regressionB * x;

    result.innerHTML += `
        <br>ط¹ظ†ط¯ X = ${x.toFixed(3)}
        â†’ Y = ${y.toFixed(6)}
    `;
};
