function fractionResult(value) {

    value = value
        .replaceAll("أ—", "*")
        .replaceAll("أ·", "/")
        .replace(/\s+/g, "");

    // ==========================================
    // طھط­ظˆظٹظ„ ط§ظ„ظƒط³ظˆط± ط¥ظ„ظ‰ ظ‚ظٹظ… ظƒط³ط±ظٹط© ط¯ظ‚ظٹظ‚ط©
    // ==========================================

    const fractionPattern =
        /(-?\d+(?:\.\d+)?)\/(-?\d+(?:\.\d+)?)/g;

    let foundFraction = false;

    value = value.replace(
        fractionPattern,
        function (match, numerator, denominator) {

            foundFraction = true;

            numerator = Number(numerator);
            denominator = Number(denominator);

            if (denominator === 0) {
                throw new Error("Math Error");
            }

            // طھط­ظˆظٹظ„ ط§ظ„ظƒط³ط± ط¥ظ„ظ‰ ط±ظ‚ظ… ط¹ط´ط±ظٹ ظ…ط¤ظ‚طھ
            // ظ„ظ„ط­ط³ط§ط¨ ط§ظ„ط¹ط§ظ…
            return `(${numerator / denominator})`;
        }
    );
// ==========================================
// طھط­ظˆظٹظ„ ط§ظ„ط¬ط°ط± ظˆط§ظ„ط¬ط°ط± ط§ظ„طھظƒط¹ظٹط¨ظٹ
// ==========================================

value = value
    .replace(/âˆڑ\(/g, "Math.sqrt(")
    .replace(/âˆ›\(/g, "Math.cbrt(");
    // ==========================================
    // ظ„ظˆ ظ…ظپظٹط´ ظƒط³ط±
    // ==========================================

    if (!foundFraction) {
        throw new Error("Not a fraction expression");
    }

    // ==========================================
    // ط§ظ„ط­ط³ط§ط¨
    // ==========================================

    let result = Function(
        `"use strict"; return (${value})`
    )();

    if (!Number.isFinite(result)) {
        throw new Error("Math Error");
    }

    // ==========================================
    // طھط­ظˆظٹظ„ ط§ظ„ظ†ط§طھط¬ ط¥ظ„ظ‰ ظƒط³ط± ظ…ط¨ط³ط·
    // ==========================================

    result = Number(result.toFixed(10));

    if (Number.isInteger(result)) {

        return {
            numerator: result,
            denominator: 1
        };
    }

    // ط§ظ„طھط¹ط§ظ…ظ„ ظ…ط¹ ط§ظ„ط³ط§ظ„ط¨
    let sign = result < 0 ? -1 : 1;

    result = Math.abs(result);

    const decimalString =
        result.toString();

    let decimalPlaces = 0;

    if (decimalString.includes(".")) {
        decimalPlaces =
            decimalString.split(".")[1].length;
    }

    let denominator =
        Math.pow(10, decimalPlaces);

    let numerator =
        Math.round(result * denominator);

    numerator *= sign;

    // ==========================================
    // طھط¨ط³ظٹط· ط§ظ„ظƒط³ط±
    // ==========================================

    const divisor =
        gcd(
            Math.abs(numerator),
            denominator
        );

    numerator /= divisor;
    denominator /= divisor;

    return {
        numerator,
        denominator
    };
}
