function tokenizeComplexExpression(str) {

    const tokens = [];
    let current = "";

    for (let i = 0; i < str.length; i++) {

        const ch = str[i];

        // =====================================
        // Operators
        // =====================================
        if (
            ch === "+" ||
            ch === "-" ||
            ch === "*" ||
            ch === "/"
        ) {

            // + ط£ظˆ - ظپظٹ ط¨ط¯ط§ظٹط© ط§ظ„ط¹ط¯ط¯
            if (
                current === "" &&
                (ch === "+" || ch === "-")
            ) {
                current += ch;
                continue;
            }

            // + ط£ظˆ - ط¨ط¹ط¯ Operator
            if (
                current === "" &&
                tokens.length > 0 &&
                (
                    tokens[tokens.length - 1] === "+" ||
                    tokens[tokens.length - 1] === "-" ||
                    tokens[tokens.length - 1] === "*" ||
                    tokens[tokens.length - 1] === "/"
                )
            ) {
                current += ch;
                continue;
            }

            if (current !== "") {
                tokens.push(current);
                current = "";
            }

            tokens.push(ch);
            continue;
        }

        current += ch;
    }

    if (current !== "") {
        tokens.push(current);
    }

    console.log("ًںں، TOKENIZER RESULT:", tokens);

    return tokens;
}

