function complexMul(a, b) {
    return new Complex(
        a.re * b.re - a.im * b.im,
        a.re * b.im + a.im * b.re
    );
}

function complexDiv(a, b) {
    const den = b.re * b.re + b.im * b.im;

    if (Math.abs(den) < 1e-15) {
        throw new Error("Division by zero");
    }

    return new Complex(
        (a.re * b.re + a.im * b.im) / den,
        (a.im * b.re - a.re * b.im) / den
    );
}

function complexAdd(a, b) {
    return new Complex(
        a.re + b.re,
        a.im + b.im
    );
}

function complexSub(a, b) {
    return new Complex(
        a.re - b.re,
        a.im - b.im
    );
}

function complexNeg(a) {
    return new Complex(-a.re, -a.im);
}

function complexSqrt(z) {
    const r = Math.hypot(z.re, z.im);

    const real = Math.sqrt(
        Math.max(0, (r + z.re) / 2)
    );

    const imagSign = z.im < 0 ? -1 : 1;

    const imag = imagSign * Math.sqrt(
        Math.max(0, (r - z.re) / 2)
    );

    return new Complex(real, imag);
}

function complexExp(z) {
    const e = Math.exp(z.re);

    return new Complex(
        e * Math.cos(z.im),
        e * Math.sin(z.im)
    );
}

function complexLn(z) {
    const modulus = Math.hypot(z.re, z.im);

    if (modulus === 0) {
        throw new Error("ln(0)");
    }

    return new Complex(
        Math.log(modulus),
        Math.atan2(z.im, z.re)
    );
}
