const dmsBtn = document.getElementById("dmsBtn");

if (dmsBtn) {
    dmsBtn.onclick = () => {

        let value = Number(display.value);

        if (!Number.isFinite(value)) return;

        // طھط­ظˆظٹظ„ ط§ظ„ظ‚ظٹظ…ط© ط¥ظ„ظ‰ ط¯ط±ط¬ط§طھ ط­ط³ط¨ ظˆط¶ط¹ ط§ظ„ط²ط§ظˆظٹط©
        if (angleMode === "RAD") {
            value = value * 180 / Math.PI;
        } 
        else if (angleMode === "GRAD") {
            value = value * 0.9;
        }

        let sign = value < 0 ? "-" : "";
        value = Math.abs(value);

        let degrees = Math.floor(value);

        let minutesFull = (value - degrees) * 60;
        let minutes = Math.floor(minutesFull);

        let seconds = (minutesFull - minutes) * 60;

        // ظ…ط¹ط§ظ„ط¬ط© ط§ظ„طھظ‚ط±ظٹط¨
        if (seconds >= 59.995) {
            seconds = 0;
            minutes++;

            if (minutes >= 60) {
                minutes = 0;
                degrees++;
            }
        }

        display.value =
            `${sign}${degrees}آ° ${minutes}â€² ${seconds.toFixed(2)}â€³`;
    };
}
