const plusMinusBtn = document.getElementById("plusMinus");

if (plusMinusBtn) {

    plusMinusBtn.onclick = function () {

        // ==========================================
        // MATRIX آ±
        // ==========================================

        if (
            currentMode === "MATRIX" &&
            window.matrixData
        ) {

            const data = window.matrixData;

            if (data.current === "") {
                return;
            }

            if (data.current.startsWith("-")) {
                data.current =
                    data.current.substring(1);
            } else {
                data.current =
                    "-" + data.current;
            }

            const input =
                document.getElementById("matrixInput");

            if (!input) return;

            // NORMAL
            if (data.type === "NORMAL") {

                const index = data.values.length;

const r = Math.floor(index / data.cols);
const c = index % data.cols;

input.textContent =
    `a${r + 1}${c + 1} = ${data.current}`;
                return;
            }

            // SKEW
            if (data.type === "SKEW") {

                const positions = [];

                for (let r = 0; r < data.size; r++) {
                    for (
                        let c = r + 1;
                        c < data.size;
                        c++
                    ) {
                        positions.push([r, c]);
                    }
                }

                const index =
                    data.values.length;

                if (index < positions.length) {

                    const [r, c] =
                        positions[index];

                    input.textContent =
                        `a${r + 1}${c + 1} = ${data.current}`;
                }

                return;
            }

            // SYMMETRIC
            if (data.type === "SYMMETRIC") {

                const positions = [];

                for (let r = 0; r < data.size; r++) {
                    for (
                        let c = r;
                        c < data.size;
                        c++
                    ) {
                        positions.push([r, c]);
                    }
                }

                const index =
                    data.values.length;

                if (index < positions.length) {

                    const [r, c] =
                        positions[index];

                    input.textContent =
                        `a${r + 1}${c + 1} = ${data.current}`;
                }

                return;
            }

            // SCALAR
            if (data.type === "SCALAR") {

                input.textContent =
                    "ط§ظ„ظ‚ظٹظ…ط© = " + data.current;

                return;
            }

        }

        // ==========================================
        // ط§ظ„ظˆط¶ط¹ ط§ظ„ط¹ط§ط¯ظٹ
        // ==========================================

        let value =
            display.value.trim();

        if (!value) return;

        if (
            /^[+-]?(?:\d+(?:\.\d+)?|\.\d+)$/.test(value)
        ) {

            if (value.startsWith("-")) {
                value = value.substring(1);
            } else {
                value = "-" + value;
            }

            display.value = value;
            answer = Number(value);

            return;
        }

        if (
            value.startsWith("-(") &&
            value.endsWith(")")
        ) {

            display.value =
                value.slice(2, -1);

        } else {

            display.value =
                "-(" + value + ")";
        }
    };
}
// =====================================
// VECTOR CALCULATIONS
// =====================================

window.calcVectorMagnitude = function () {

    const A = document.getElementById("vectorA");
    const R = document.getElementById("vectorRes");

    if (!A || !R) return;

    const a = A.value
        .split(",")
        .map(Number);

    if (!a.length || a.some(Number.isNaN)) {
        R.innerHTML = "ط£ط¯ط®ظ„ A ط¨ط´ظƒظ„ طµط­ظٹط­";
        return;
    }

    const mag = Math.sqrt(
        a.reduce((sum, x) => sum + x * x, 0)
    );

    R.innerHTML = `|A| = ${mag.toFixed(6)}`;
};


window.calcVectorDot = function () {

    const A = document.getElementById("vectorA");
    const B = document.getElementById("vectorB");
    const R = document.getElementById("vectorRes");

    if (!A || !B || !R) return;

    const a = A.value.split(",").map(Number);
    const b = B.value.split(",").map(Number);

    if (
        !a.length ||
        !b.length ||
        a.some(Number.isNaN) ||
        b.some(Number.isNaN) ||
        a.length !== b.length
    ) {
        R.innerHTML = "A ظˆ B ظٹط¬ط¨ ط£ظ† ظٹظƒظˆظ†ط§ ط¨ظ†ظپط³ ط¹ط¯ط¯ ط§ظ„ط¹ظ†ط§طµط±";
        return;
    }

    const dot = a.reduce(
        (sum, x, i) => sum + x * b[i],
        0
    );

    R.innerHTML = `A آ· B = ${dot.toFixed(6)}`;
};
window.calcVectorProjection = function () {

    const A = document.getElementById("vectorA");
    const B = document.getElementById("vectorB");
    const R = document.getElementById("vectorRes");

    if (!A || !B || !R) return;

    const a = A.value.split(",").map(Number);
    const b = B.value.split(",").map(Number);

    if (
        !a.length ||
        !b.length ||
        a.some(Number.isNaN) ||
        b.some(Number.isNaN) ||
        a.length !== b.length
    ) {
        R.innerHTML = "A ظˆ B ظٹط¬ط¨ ط£ظ† ظٹظƒظˆظ†ط§ ط¨ظ†ظپط³ ط¹ط¯ط¯ ط§ظ„ط¹ظ†ط§طµط±";
        return;
    }

    const dot = a.reduce(
        (sum, x, i) => sum + x * b[i],
        0
    );

    const bMag2 = b.reduce(
        (sum, x) => sum + x * x,
        0
    );

    if (bMag2 === 0) {
        R.innerHTML = "ERROR";
        return;
    }

    const factor = dot / bMag2;

    const projection = b.map(
        x => factor * x
    );

    R.innerHTML =
        `Proj(A,B) = (${projection
            .map(x => x.toFixed(6))
            .join(", ")})`;
};

window.calcVectorCross = function () {

    const A = document.getElementById("vectorA");
    const B = document.getElementById("vectorB");
    const R = document.getElementById("vectorRes");

    if (!A || !B || !R) return;

    const a = A.value.split(",").map(Number);
    const b = B.value.split(",").map(Number);

    if (
        a.length !== 3 ||
        b.length !== 3 ||
        a.some(Number.isNaN) ||
        b.some(Number.isNaN)
    ) {
        R.innerHTML = "A أ— B ظٹط­طھط§ط¬ ظ…طھط¬ظ‡ظٹظ† 3D";
        return;
    }

    const x = a[1] * b[2] - a[2] * b[1];
    const y = a[2] * b[0] - a[0] * b[2];
    const z = a[0] * b[1] - a[1] * b[0];

    R.innerHTML =
        `A أ— B = (${x.toFixed(6)}, ${y.toFixed(6)}, ${z.toFixed(6)})`;
};
window.calcVectorAdd = function () {

    const A = document.getElementById("vectorA");
    const B = document.getElementById("vectorB");
    const R = document.getElementById("vectorRes");

    if (!A || !B || !R) return;

    const a = A.value.split(",").map(Number);
    const b = B.value.split(",").map(Number);

    if (
        a.length !== b.length ||
        a.some(Number.isNaN) ||
        b.some(Number.isNaN)
    ) {
        R.innerHTML = "A ظˆ B ظٹط¬ط¨ ط£ظ† ظٹظƒظˆظ†ط§ ط¨ظ†ظپط³ ط¹ط¯ط¯ ط§ظ„ط¹ظ†ط§طµط±";
        return;
    }

    const result = a.map((x, i) => x + b[i]);

    R.innerHTML =
        `A + B = (${result.map(x => x.toFixed(6)).join(", ")})`;
};


window.calcVectorSub = function () {

    const A = document.getElementById("vectorA");
    const B = document.getElementById("vectorB");
    const R = document.getElementById("vectorRes");

    if (!A || !B || !R) return;

    const a = A.value.split(",").map(Number);
    const b = B.value.split(",").map(Number);

    if (
        a.length !== b.length ||
        a.some(Number.isNaN) ||
        b.some(Number.isNaN)
    ) {
        R.innerHTML = "A ظˆ B ظٹط¬ط¨ ط£ظ† ظٹظƒظˆظ†ط§ ط¨ظ†ظپط³ ط¹ط¯ط¯ ط§ظ„ط¹ظ†ط§طµط±";
        return;
    }

    const result = a.map((x, i) => x - b[i]);

    R.innerHTML =
        `A âˆ’ B = (${result.map(x => x.toFixed(6)).join(", ")})`;
};
window.calcVectorAngle = function () {

    const A = document.getElementById("vectorA");
    const B = document.getElementById("vectorB");
    const R = document.getElementById("vectorRes");

    if (!A || !B || !R) return;

    const a = A.value.split(",").map(Number);
    const b = B.value.split(",").map(Number);

    if (
        a.length !== b.length ||
        !a.length ||
        a.some(Number.isNaN) ||
        b.some(Number.isNaN)
    ) {
        R.innerHTML = "A ظˆ B ظٹط¬ط¨ ط£ظ† ظٹظƒظˆظ†ط§ ط¨ظ†ظپط³ ط¹ط¯ط¯ ط§ظ„ط¹ظ†ط§طµط±";
        return;
    }

    const dot = a.reduce((s, x, i) => s + x * b[i], 0);

    const magA = Math.sqrt(a.reduce((s, x) => s + x * x, 0));
    const magB = Math.sqrt(b.reduce((s, x) => s + x * x, 0));

    if (!magA || !magB) {
        R.innerHTML = "ظ„ط§ ظٹظ…ظƒظ† ط­ط³ط§ط¨ ط§ظ„ط²ط§ظˆظٹط©";
        return;
    }

    const cosTheta = Math.max(
        -1,
        Math.min(1, dot / (magA * magB))
    );

    const angle =
        Math.acos(cosTheta) * 180 / Math.PI;

    R.innerHTML = `خ¸ = ${angle.toFixed(6)}آ°`;
};
window.calcVectorUnit = function () {

    const A = document.getElementById("vectorA");
    const R = document.getElementById("vectorRes");

    if (!A || !R) return;

    const a = A.value.split(",").map(Number);

    if (!a.length || a.some(Number.isNaN)) {
        R.innerHTML = "ط£ط¯ط®ظ„ A ط¨ط´ظƒظ„ طµط­ظٹط­";
        return;
    }

    const mag = Math.sqrt(
        a.reduce((sum, x) => sum + x * x, 0)
    );

    if (mag === 0) {
        R.innerHTML = "ظ„ط§ ظٹظ…ظƒظ† ط¹ظ…ظ„ Unit Vector ظ„ظ„طµظپط±";
        return;
    }

    const unit = a.map(x => x / mag);

    R.innerHTML =
        `Unit A = (${unit.map(x => x.toFixed(6)).join(", ")})`;
};
