// ==========================================
// ًں§ھ ظƒطھط§ط¨ط© ط¯ط§ط®ظ„ ط­ظ‚ظ„ ط§ظ„ظƒظٹظ…ظٹط§ط،
// ==========================================

window.chemistryWrite = function (value) {

    const activeId =
        window.activeChemistryField;

    if (!activeId) {

        console.log(
            "ًں§ھ ظ„ط§ طھظˆط¬ط¯ ط®ط§ظ†ط© ظƒظٹظ…ظٹط§ط، ظ†ط´ط·ط©"
        );

        return;
    }

    const field =
        document.getElementById(activeId);

    if (!field) return;


    // ------------------------------------------
    // ط§ظ„ط­ط±ظˆظپ
    // ------------------------------------------

    if (/^[a-zA-Z]$/.test(value)) {

        let letter = value.toLowerCase();

        if (window.chemistryShift) {

            letter =
                letter.toUpperCase();

            window.chemistryShift = false;

            const shiftBtn =
                document.getElementById(
                    "chemShiftBtn"
                );

            if (shiftBtn) {
                shiftBtn.textContent = "SHIFT";
            }
        }

        field.value += letter;

        console.log(
            "ًں§ھ LETTER:",
            letter
        );

        return;
    }


    // ------------------------------------------
    // ط§ظ„ط£ط±ظ‚ط§ظ…
    // ------------------------------------------

    if (/^[0-9]$/.test(value)) {

        field.value += value;

        return;
    }


    // ------------------------------------------
    // ط§ظ„ظ†ظ‚ط·ط©
    // ------------------------------------------

    if (value === ".") {

    field.value += ".";

    return;
}


    // ------------------------------------------
    // ط¨ط§ظ‚ظٹ ط§ظ„ط±ظ…ظˆط²
    // ------------------------------------------

    if (
        [
            "(",
            ")",
            "+",
            "-",
            "أ—",
            "أ·",
            ","
        ].includes(value)
    ) {

        field.value += value;

        return;
    }
};



