// ==========================================
// ط­ط³ط§ط¨ ط§ظ„ظƒطھظ„ط© ط§ظ„ظ…ظˆظ„ظٹط©
// ظٹط¯ط¹ظ…:
// H2O
// CO2
// Ca(OH)2
// Al2(SO4)3
// ==========================================

window.calculateMolarMass = function () {

    const input =
        document.getElementById("chemFormulaInput");

    const result =
        document.getElementById("chemMolarResult");

    if (!input || !result) return;

    const formula = input.value.trim();

    if (!formula) {
        result.innerHTML = "â‌Œ ط£ط¯ط®ظ„ ط§ظ„طµظٹط؛ط© ط§ظ„ظƒظٹظ…ظٹط§ط¦ظٹط©";
        return;
    }

    try {

        let position = 0;


        function parseNumber() {

            let number = "";

            while (
                position < formula.length &&
                /[0-9]/.test(formula[position])
            ) {
                number += formula[position];
                position++;
            }

            return number
                ? Number(number)
                : 1;
        }


        function parseGroup(endChar = null) {

            let total = 0;

            while (position < formula.length) {

                // ظ†ظ‡ط§ظٹط© ط§ظ„ظ‚ظˆط³
                if (
                    endChar &&
                    formula[position] === endChar
                ) {
                    position++;
                    break;
                }


                // ظپطھط­ ظ‚ظˆط³
                if (formula[position] === "(") {

                    position++;

                    const groupMass =
                        parseGroup(")");

                    const multiplier =
                        parseNumber();

                    total +=
                        groupMass * multiplier;

                    continue;
                }


                // ط§ظ„ط¹ظ†طµط±
                if (/[A-Z]/.test(formula[position])) {

                    let symbol =
                        formula[position];

                    position++;

                    // ط§ظ„ط­ط±ظپ ط§ظ„ط«ط§ظ†ظٹ
                    if (
                        position < formula.length &&
                        /[a-z]/.test(formula[position])
                    ) {
                        symbol +=
                            formula[position];

                        position++;
                    }

                    if (
                        !Object.prototype.hasOwnProperty.call(
                            atomicMasses,
                            symbol
                        )
                    ) {
                        throw new Error(
                            `ط§ظ„ط¹ظ†طµط± ${symbol} ط؛ظٹط± ظ…ط¹ط±ظˆظپ`
                        );
                    }

                    const count =
                        parseNumber();

                    total +=
                        atomicMasses[symbol] * count;

                    continue;
                }


                throw new Error(
                    `ط±ظ…ط² ط؛ظٹط± طµط­ظٹط­: ${formula[position]}`
                );
            }

            if (endChar && formula[position - 1] !== endChar) {
                throw new Error("ظ‚ظˆط³ ط؛ظٹط± ظ…ط؛ظ„ظ‚");
            }

            return total;
        }


        const mass = parseGroup();
window.lastChemistryResult = mass;

        if (position !== formula.length) {
            throw new Error("طµظٹط؛ط© ط؛ظٹط± طµط­ظٹط­ط©");
        }


        result.innerHTML =
            `âœ… M = ${mass.toFixed(3)} g/mol`;

        console.log(
            "ًں§ھ MOLAR MASS:",
            formula,
            mass
        );

    } catch (error) {

        result.innerHTML =
            `â‌Œ ${error.message}`;
    }
};

