// ًں§® ط­ط³ط§ط¨ ط§ظ„طھط®ظپظٹظپ
// ==========================================

window.calculateChemistryDilution = function () {

    const C1 =
        Number(
            document.getElementById(
                "chemDilutionC1"
            )?.value
        );

    const V1 =
        Number(
            document.getElementById(
                "chemDilutionV1"
            )?.value
        );

    const C2 =
        Number(
            document.getElementById(
                "chemDilutionC2"
            )?.value
        );

    const V2 =
        Number(
            document.getElementById(
                "chemDilutionV2"
            )?.value
        );

    const unknown =
        document.getElementById(
            "chemDilutionUnknown"
        )?.value;

    const result =
        document.getElementById(
            "chemDilutionResult"
        );

    if (!result) return;


    // ======================================
    // ط­ط³ط§ط¨ C1
    // C1 = C2 أ— V2 / V1
    // ======================================

    if (unknown === "C1") {

        if (
            !Number.isFinite(C2) ||
            !Number.isFinite(V2) ||
            !Number.isFinite(V1)
        ) {
            result.innerHTML =
                "â‌Œ ط£ط¯ط®ظ„ Câ‚‚ ظˆ Vâ‚پ ظˆ Vâ‚‚";
            return;
        }

        if (V1 === 0) {
            result.innerHTML =
                "â‌Œ Vâ‚پ ظ„ط§ ظٹظ…ظƒظ† ط£ظ† ظٹط³ط§ظˆظٹ طµظپط±";
            return;
        }

        const answer =
            (C2 * V2) / V1;

        result.innerHTML =
            `âœ… Câ‚پ = ${answer.toFixed(6)} mol/L`;

        return;
    }


    // ======================================
    // ط­ط³ط§ط¨ V1
    // V1 = C2 أ— V2 / C1
    // ======================================

    if (unknown === "V1") {

        if (
            !Number.isFinite(C2) ||
            !Number.isFinite(V2) ||
            !Number.isFinite(C1)
        ) {
            result.innerHTML =
                "â‌Œ ط£ط¯ط®ظ„ Câ‚پ ظˆ Câ‚‚ ظˆ Vâ‚‚";
            return;
        }

        if (C1 === 0) {
            result.innerHTML =
                "â‌Œ Câ‚پ ظ„ط§ ظٹظ…ظƒظ† ط£ظ† ظٹط³ط§ظˆظٹ طµظپط±";
            return;
        }

        const answer =
            (C2 * V2) / C1;

        result.innerHTML =
            `âœ… Vâ‚پ = ${answer.toFixed(6)} L`;

        return;
    }


    // ======================================
    // ط­ط³ط§ط¨ C2
    // C2 = C1 أ— V1 / V2
    // ======================================

    if (unknown === "C2") {

        if (
            !Number.isFinite(C1) ||
            !Number.isFinite(V1) ||
            !Number.isFinite(V2)
        ) {
            result.innerHTML =
                "â‌Œ ط£ط¯ط®ظ„ Câ‚پ ظˆ Vâ‚پ ظˆ Vâ‚‚";
            return;
        }

        if (V2 === 0) {
            result.innerHTML =
                "â‌Œ Vâ‚‚ ظ„ط§ ظٹظ…ظƒظ† ط£ظ† ظٹط³ط§ظˆظٹ طµظپط±";
            return;
        }

        const answer =
            (C1 * V1) / V2;

        result.innerHTML =
            `âœ… Câ‚‚ = ${answer.toFixed(6)} mol/L`;

        return;
    }


    // ======================================
    // ط­ط³ط§ط¨ V2
    // V2 = C1 أ— V1 / C2
    // ======================================

    if (unknown === "V2") {

        if (
            !Number.isFinite(C1) ||
            !Number.isFinite(V1) ||
            !Number.isFinite(C2)
        ) {
            result.innerHTML =
                "â‌Œ ط£ط¯ط®ظ„ Câ‚پ ظˆ Vâ‚پ ظˆ Câ‚‚";
            return;
        }

        if (C2 === 0) {
            result.innerHTML =
                "â‌Œ Câ‚‚ ظ„ط§ ظٹظ…ظƒظ† ط£ظ† ظٹط³ط§ظˆظٹ طµظپط±";
            return;
        }

        const answer =
            (C1 * V1) / C2;

        result.innerHTML =
            `âœ… Vâ‚‚ = ${answer.toFixed(6)} L`;

        return;
    }
};
