// ==========================================
// ًں§® ط­ط³ط§ط¨ q = m أ— c أ— خ”T
// ==========================================

window.calculateChemistryHeatEnergy = function () {

    const m =
        Number(
            document.getElementById(
                "chemHeatMass"
            )?.value
        );

    const c =
        Number(
            document.getElementById(
                "chemHeatSpecific"
            )?.value
        );

    const deltaT =
        Number(
            document.getElementById(
                "chemHeatDeltaT"
            )?.value
        );

    const q =
        Number(
            document.getElementById(
                "chemHeatQ"
            )?.value
        );

    const unknown =
        document.getElementById(
            "chemHeatUnknown"
        )?.value;

    const result =
        document.getElementById(
            "chemHeatResult"
        );

    if (!result) return;


    // ======================================
    // ط­ط³ط§ط¨ q
    // q = m أ— c أ— خ”T
    // ======================================

    if (unknown === "q") {

        if (
            !Number.isFinite(m) ||
            !Number.isFinite(c) ||
            !Number.isFinite(deltaT)
        ) {

            result.innerHTML =
                "â‌Œ ط£ط¯ط®ظ„ m ظˆ c ظˆ خ”T";

            return;
        }

        const answer =
            m * c * deltaT;

        result.innerHTML =
            `âœ… q = ${answer.toFixed(6)} J`;

        return;
    }


    // ======================================
    // ط­ط³ط§ط¨ m
    // m = q / (c أ— خ”T)
    // ======================================

    if (unknown === "m") {

        if (
            !Number.isFinite(q) ||
            !Number.isFinite(c) ||
            !Number.isFinite(deltaT)
        ) {

            result.innerHTML =
                "â‌Œ ط£ط¯ط®ظ„ q ظˆ c ظˆ خ”T";

            return;
        }

        const denominator =
            c * deltaT;

        if (denominator === 0) {

            result.innerHTML =
                "â‌Œ ظ„ط§ ظٹظ…ظƒظ† ط§ظ„ظ‚ط³ظ…ط© ط¹ظ„ظ‰ طµظپط±";

            return;
        }

        const answer =
            q / denominator;

        result.innerHTML =
            `âœ… m = ${answer.toFixed(6)} g`;

        return;
    }


    // ======================================
    // ط­ط³ط§ط¨ c
    // c = q / (m أ— خ”T)
    // ======================================

    if (unknown === "c") {

        if (
            !Number.isFinite(q) ||
            !Number.isFinite(m) ||
            !Number.isFinite(deltaT)
        ) {

            result.innerHTML =
                "â‌Œ ط£ط¯ط®ظ„ q ظˆ m ظˆ خ”T";

            return;
        }

        const denominator =
            m * deltaT;

        if (denominator === 0) {

            result.innerHTML =
                "â‌Œ ظ„ط§ ظٹظ…ظƒظ† ط§ظ„ظ‚ط³ظ…ط© ط¹ظ„ظ‰ طµظپط±";

            return;
        }

        const answer =
            q / denominator;

        result.innerHTML =
            `âœ… c = ${answer.toFixed(6)} J/gآ°C`;

        return;
    }


    // ======================================
    // ط­ط³ط§ط¨ خ”T
    // خ”T = q / (m أ— c)
    // ======================================

    if (unknown === "deltaT") {

        if (
            !Number.isFinite(q) ||
            !Number.isFinite(m) ||
            !Number.isFinite(c)
        ) {

            result.innerHTML =
                "â‌Œ ط£ط¯ط®ظ„ q ظˆ m ظˆ c";

            return;
        }

        const denominator =
            m * c;

        if (denominator === 0) {

            result.innerHTML =
                "â‌Œ ظ„ط§ ظٹظ…ظƒظ† ط§ظ„ظ‚ط³ظ…ط© ط¹ظ„ظ‰ طµظپط±";

            return;
        }

        const answer =
            q / denominator;

        result.innerHTML =
            `âœ… خ”T = ${answer.toFixed(6)} آ°C`;

        return;
    }
};
