// ==========================================
// ًں§® ط­ط³ط§ط¨ PV = nRT
// ==========================================

window.calculateChemistryIdealGas = function () {

    const P =
        Number(document.getElementById("chemGasP")?.value);

    const V =
        Number(document.getElementById("chemGasV")?.value);

    const n =
        Number(document.getElementById("chemGasN")?.value);

    const T =
        Number(document.getElementById("chemGasT")?.value);

    const R =
        Number(document.getElementById("chemGasR")?.value);

    const unknown =
        document.getElementById("chemGasUnknown")?.value;

    const result =
        document.getElementById("chemGasResult");

    if (!result) return;

    if (!Number.isFinite(R) || R === 0) {

        result.innerHTML =
            "â‌Œ ط«ط§ط¨طھ ط§ظ„ط؛ط§ط² R ط؛ظٹط± طµط­ظٹط­";

        return;
    }


    // ======================================
    // ط­ط³ط§ط¨ P
    // P = nRT / V
    // ======================================

    if (unknown === "P") {

        if (
            !Number.isFinite(n) ||
            !Number.isFinite(T) ||
            !Number.isFinite(V)
        ) {

            result.innerHTML =
                "â‌Œ ط£ط¯ط®ظ„ n ظˆ T ظˆ V";

            return;
        }

        if (V === 0) {

            result.innerHTML =
                "â‌Œ ط§ظ„ط­ط¬ظ… V ظ„ط§ ظٹظ…ظƒظ† ط£ظ† ظٹط³ط§ظˆظٹ طµظپط±";

            return;
        }

        const answer =
            (n * R * T) / V;

        result.innerHTML =
            `âœ… P = ${answer.toFixed(6)} atm`;

        return;
    }


    // ======================================
    // ط­ط³ط§ط¨ V
    // V = nRT / P
    // ======================================

    if (unknown === "V") {

        if (
            !Number.isFinite(n) ||
            !Number.isFinite(T) ||
            !Number.isFinite(P)
        ) {

            result.innerHTML =
                "â‌Œ ط£ط¯ط®ظ„ P ظˆ n ظˆ T";

            return;
        }

        if (P === 0) {

            result.innerHTML =
                "â‌Œ ط§ظ„ط¶ط؛ط· P ظ„ط§ ظٹظ…ظƒظ† ط£ظ† ظٹط³ط§ظˆظٹ طµظپط±";

            return;
        }

        const answer =
            (n * R * T) / P;

        result.innerHTML =
            `âœ… V = ${answer.toFixed(6)} L`;

        return;
    }


    // ======================================
    // ط­ط³ط§ط¨ n
    // n = PV / RT
    // ======================================

    if (unknown === "n") {

        if (
            !Number.isFinite(P) ||
            !Number.isFinite(V) ||
            !Number.isFinite(T)
        ) {

            result.innerHTML =
                "â‌Œ ط£ط¯ط®ظ„ P ظˆ V ظˆ T";

            return;
        }

        if (T === 0) {

            result.innerHTML =
                "â‌Œ ط¯ط±ط¬ط© ط§ظ„ط­ط±ط§ط±ط© T ظ„ط§ ظٹظ…ظƒظ† ط£ظ† طھط³ط§ظˆظٹ طµظپط±";

            return;
        }

        const answer =
            (P * V) / (R * T);

        result.innerHTML =
            `âœ… n = ${answer.toFixed(6)} mol`;

        return;
    }


    // ======================================
    // ط­ط³ط§ط¨ T
    // T = PV / nR
    // ======================================

    if (unknown === "T") {

        if (
            !Number.isFinite(P) ||
            !Number.isFinite(V) ||
            !Number.isFinite(n)
        ) {

            result.innerHTML =
                "â‌Œ ط£ط¯ط®ظ„ P ظˆ V ظˆ n";

            return;
        }

        if (n === 0) {

            result.innerHTML =
                "â‌Œ ط¹ط¯ط¯ ط§ظ„ظ…ظˆظ„ط§طھ n ظ„ط§ ظٹظ…ظƒظ† ط£ظ† ظٹط³ط§ظˆظٹ طµظپط±";

            return;
        }

        const answer =
            (P * V) / (n * R);

        result.innerHTML =
            `âœ… T = ${answer.toFixed(6)} K`;

        return;
    }
};
