        if (V1 === 0 || T2 === 0) {
            result.innerHTML =
                "â‌Œ ط§ظ„ظ…ظ‚ط§ظ… ظ„ط§ ظٹظ…ظƒظ† ط£ظ† ظٹط³ط§ظˆظٹ طµظپط±";
            return;
        }

        const answer =
            (P2 * V2 * T1) / (T2 * V1);

        result.innerHTML =
            `âœ… Pâ‚پ = ${answer.toFixed(6)}`;

