// ==========================================
// ًں§® ط­ط³ط§ط¨ Kc
// ==========================================

window.calculateChemistryKc = function () {

    const Acoef = Number(
        document.getElementById("chemKcAcoef")?.value
    );

    const Aconc = Number(
        document.getElementById("chemKcAconc")?.value
    );

    const Bcoef = Number(
        document.getElementById("chemKcBcoef")?.value
    );

    const Bconc = Number(
        document.getElementById("chemKcBconc")?.value
    );

    const Ccoef = Number(
        document.getElementById("chemKcCcoef")?.value
    );

    const Cconc = Number(
        document.getElementById("chemKcCconc")?.value
    );

    const Dcoef = Number(
        document.getElementById("chemKcDcoef")?.value
    );

    const Dconc = Number(
        document.getElementById("chemKcDconc")?.value
    );

    const result =
        document.getElementById("chemKcResult");

    if (!result) return;


    // ======================================
    // ط§ظ„طھط­ظ‚ظ‚
    // ======================================

    if (
        !Number.isFinite(Acoef) ||
        !Number.isFinite(Aconc) ||
        !Number.isFinite(Bcoef) ||
        !Number.isFinite(Bconc) ||
        !Number.isFinite(Ccoef) ||
        !Number.isFinite(Cconc) ||
        !Number.isFinite(Dcoef) ||
        !Number.isFinite(Dconc)
    ) {

        result.innerHTML =
            "â‌Œ ط£ط¯ط®ظ„ ط¬ظ…ظٹط¹ ط§ظ„ظ‚ظٹظ…";

        return;
    }


    if (
        Acoef <= 0 ||
        Bcoef <= 0 ||
        Ccoef <= 0 ||
        Dcoef <= 0
    ) {

        result.innerHTML =
            "â‌Œ ط§ظ„ظ…ط¹ط§ظ…ظ„ط§طھ ظٹط¬ط¨ ط£ظ† طھظƒظˆظ† ط£ظƒط¨ط± ظ…ظ† طµظپط±";

        return;
    }


    if (
        Aconc < 0 ||
        Bconc < 0 ||
        Cconc < 0 ||
        Dconc < 0
    ) {

        result.innerHTML =
            "â‌Œ ط§ظ„طھط±ظƒظٹط² ظ„ط§ ظٹظ…ظƒظ† ط£ظ† ظٹظƒظˆظ† ط³ط§ظ„ط¨ظ‹ط§";

        return;
    }


    // ======================================
    // ط§ظ„ظ…ظ‚ط§ظ…
    // ======================================

    const denominator =
        Math.pow(Aconc, Acoef) *
        Math.pow(Bconc, Bcoef);


    if (denominator === 0) {

        result.innerHTML =
            "â‌Œ ظ„ط§ ظٹظ…ظƒظ† ط£ظ† ظٹظƒظˆظ† ط§ظ„ظ…ظ‚ط§ظ… طµظپط±ظ‹ط§";

        return;
    }


    // ======================================
    // ط§ظ„ط¨ط³ط·
    // ======================================

    const numerator =
        Math.pow(Cconc, Ccoef) *
        Math.pow(Dconc, Dcoef);


    // ======================================
    // Kc
    // ======================================

    const Kc =
        numerator / denominator;


    if (!Number.isFinite(Kc)) {

        result.innerHTML =
            "â‌Œ ط§ظ„ظ†طھظٹط¬ط© ظƒط¨ظٹط±ط© ط¬ط¯ظ‹ط§ ط£ظˆ ط؛ظٹط± طµط§ظ„ط­ط©";

        return;
    }


    result.innerHTML =
        `âœ… Kc = ${Kc.toFixed(6)}`;

    console.log(
        "âڑ–ï¸ڈ Kc:",
        Kc
    );
};
