window.calculateChemistryPH = function () {

    const mode =
        document.getElementById("chemPHMode")?.value;

    const result =
        document.getElementById("chemPHResult");

    if (!result) return;


    // ======================================
    // pH ظ…ظ† H+
    // ======================================

    if (mode === "fromH") {

        const H =
            Number(
                document.getElementById("chemPHH")?.value
            );

        if (
            !Number.isFinite(H) ||
            H <= 0
        ) {

            result.innerHTML =
                "â‌Œ طھط±ظƒظٹط² Hâپ؛ ظٹط¬ط¨ ط£ظ† ظٹظƒظˆظ† ط£ظƒط¨ط± ظ…ظ† طµظپط±";

            return;
        }

        const pH =
            -Math.log10(H);

        result.innerHTML =
            `âœ… pH = ${pH.toFixed(6)}`;

        console.log(
            "ًں§ھ pH:",
            pH
        );

        return;
    }


    // ======================================
    // H+ ظ…ظ† pH
    // ======================================

    if (mode === "fromPH") {

        const pH =
            Number(
                document.getElementById("chemPHValue")?.value
            );

        if (!Number.isFinite(pH)) {

            result.innerHTML =
                "â‌Œ ط£ط¯ط®ظ„ ظ‚ظٹظ…ط© pH";

            return;
        }

        const H =
            Math.pow(10, -pH);

        result.innerHTML =
            `âœ… [Hâپ؛] = ${H.toExponential(6)} mol/L`;

        console.log(
            "ًں§ھ H+:",
            H
        );
    }
};
