// ==========================================
// ًں§® ط­ط³ط§ط¨ Ka
// ==========================================

window.calculateChemistryKa = function () {

    const H =
        Number(
            document.getElementById("chemKaH")?.value
        );

    const A =
        Number(
            document.getElementById("chemKaA")?.value
        );

    const HA =
        Number(
            document.getElementById("chemKaHA")?.value
        );

    const result =
        document.getElementById("chemKaResult");

    if (!result) return;


    // ======================================
    // ط§ظ„طھط­ظ‚ظ‚ ظ…ظ† ط§ظ„ظ‚ظٹظ…
    // ======================================

    if (
        !Number.isFinite(H) ||
        !Number.isFinite(A) ||
        !Number.isFinite(HA)
    ) {

        result.innerHTML =
            "â‌Œ ط£ط¯ط®ظ„ ط¬ظ…ظٹط¹ ط§ظ„ظ‚ظٹظ…";

        return;
    }


    if (H < 0 || A < 0) {

        result.innerHTML =
            "â‌Œ ط§ظ„طھط±ظƒظٹط² ظ„ط§ ظٹظ…ظƒظ† ط£ظ† ظٹظƒظˆظ† ط³ط§ظ„ط¨ظ‹ط§";

        return;
    }


    if (HA <= 0) {

        result.innerHTML =
            "â‌Œ طھط±ظƒظٹط² HA ظٹط¬ط¨ ط£ظ† ظٹظƒظˆظ† ط£ظƒط¨ط± ظ…ظ† طµظپط±";

        return;
    }


    // ======================================
    // Ka
    // ======================================

    const Ka =
        (H * A) / HA;


    if (!Number.isFinite(Ka)) {

        result.innerHTML =
            "â‌Œ ط§ظ„ظ†طھظٹط¬ط© ط؛ظٹط± طµط§ظ„ط­ط©";

        return;
    }


    result.innerHTML =
        `âœ… Ka = ${Ka.toExponential(6)}`;

    console.log(
        "ًں”´ Ka:",
        Ka
    );
};
