// ًں§® ط­ط³ط§ط¨ ظ†طµظپ ط§ظ„ط¹ظ…ط±
// ==========================================

window.calculateChemistryHalfLife = function () {

    const order =
        document.getElementById(
            "chemHalfLifeOrder"
        )?.value;

    const result =
        document.getElementById(
            "chemHalfLifeResult"
        );

    if (!result) return;


    const k =
        Number(
            document.getElementById(
                "chemHalfK"
            )?.value
        );

    const A0 =
        Number(
            document.getElementById(
                "chemHalfA0"
            )?.value
        );


    // ======================================
    // ط§ظ„طھط­ظ‚ظ‚ ظ…ظ† k
    // ======================================

    if (!Number.isFinite(k) || k <= 0) {

        result.innerHTML =
            "â‌Œ ط«ط§ط¨طھ ط§ظ„ط³ط±ط¹ط© k ظٹط¬ط¨ ط£ظ† ظٹظƒظˆظ† ط£ظƒط¨ط± ظ…ظ† طµظپط±";

        return;
    }


    // ======================================
    // ط§ظ„ط±طھط¨ط© طµظپط±
    // ======================================

    if (order === "zero") {

        if (!Number.isFinite(A0) || A0 <= 0) {

            result.innerHTML =
                "â‌Œ ط§ظ„طھط±ظƒظٹط² ط§ظ„ط§ط¨طھط¯ط§ط¦ظٹ ظٹط¬ط¨ ط£ظ† ظٹظƒظˆظ† ط£ظƒط¨ط± ظ…ظ† طµظپط±";

            return;
        }

        const halfLife =
            A0 / (2 * k);

        result.innerHTML =
            `âœ… tâ‚پ/â‚‚ = ${halfLife.toFixed(6)} s`;

        console.log(
            "âڈ³ Zero Order Half-Life:",
            halfLife
        );

        return;
    }


    // ======================================
    // ط§ظ„ط±طھط¨ط© ط§ظ„ط£ظˆظ„ظ‰
    // ======================================

    if (order === "first") {

        const halfLife =
            Math.log(2) / k;

        result.innerHTML =
            `âœ… tâ‚پ/â‚‚ = ${halfLife.toFixed(6)} s`;

        console.log(
            "âڈ³ First Order Half-Life:",
            halfLife
        );

        return;
    }


    // ======================================
    // ط§ظ„ط±طھط¨ط© ط§ظ„ط«ط§ظ†ظٹط©
    // ======================================

    if (order === "second") {

        if (!Number.isFinite(A0) || A0 <= 0) {

            result.innerHTML =
                "â‌Œ ط§ظ„طھط±ظƒظٹط² ط§ظ„ط§ط¨طھط¯ط§ط¦ظٹ ظٹط¬ط¨ ط£ظ† ظٹظƒظˆظ† ط£ظƒط¨ط± ظ…ظ† طµظپط±";

            return;
        }

        const halfLife =
            1 / (k * A0);

        result.innerHTML =
            `âœ… tâ‚پ/â‚‚ = ${halfLife.toFixed(6)} s`;

        console.log(
            "âڈ³ Second Order Half-Life:",
            halfLife
        );
    }
};
