window.programmingWrite = function (value) {

    const field =
        document.getElementById(
            window.activeProgrammingField
        );

    if (!field) return;

    field.value += value.toUpperCase();
};


// ==========================================
// ًں§® ط§ظ„طھط­ظˆظٹظ„
// ==========================================

window.calculateProgrammingBases = function () {

    const input =
        document.getElementById(
            "programmingNumberInput"
        );

    const base =
        Number(
            document.getElementById(
                "programmingBase"
            )?.value
        );

    const result =
        document.getElementById(
            "programmingBasesResult"
        );

    if (!input || !result) return;

    const value =
        input.value.trim();

    if (!value) {
        result.innerHTML =
            "â‌Œ ط£ط¯ط®ظ„ ط±ظ‚ظ…ظ‹ط§";
        return;
    }

    try {

        const decimal =
            parseInt(value, base);

        if (
            !Number.isFinite(decimal) ||
            decimal < 0
        ) {
            throw new Error(
                "ط±ظ‚ظ… ط؛ظٹط± طµط­ظٹط­"
            );
        }

        result.innerHTML = `
            DEC = ${decimal}<br>
            BIN = ${decimal.toString(2)}<br>
            OCT = ${decimal.toString(8)}<br>
            HEX = ${decimal.toString(16).toUpperCase()}
        `;

        window.lastProgrammingResult =
            decimal;

    } catch (error) {

        result.innerHTML =
            `â‌Œ ${error.message}`;
    }
};
// ==========================================
// ًں’» ظƒطھط§ط¨ط© ظپظٹ ط­ظ‚ظ„ ط§ظ„ط¨ط±ظ…ط¬ط©
// ==========================================

window.programmingWrite = function (value) {

    let field =
        document.getElementById(
            window.activeProgrammingField
        );

    // ظ„ظˆ ظ…ظپظٹط´ ط®ط§ظ†ط© ظ†ط´ط·ط©طŒ ط§ط³طھط®ط¯ظ… ط®ط§ظ†ط© AND ط§ظ„ط£ظˆظ„ظ‰
    if (!field) {
        field =
            document.getElementById("programmingAND_A");
    }

    if (!field) return;

    field.value += String(value).toUpperCase();
};
window.setupProgrammingKeys = function () {

    document.body.classList.add(
        "programming-mode"
    );

    


    const scientificGrid =
        document.querySelector(".scientific-grid");

    if (scientificGrid) {

        scientificGrid.innerHTML = "";

        const keys = [
    "AC", "DEL", "A", "B", "C",
    "D", "E", "F", "(", ")",
    "AND", "OR", "XOR", "NOT", "<<",
    ">>", "BIN", "OCT", "DEC", "HEX"
];

        keys.forEach(value => {

    const button =
        document.createElement("button");

    button.textContent = value;

    button.onclick = function () {

        if (value === "AC") {

            programmingClear();
            return;
        }

        if (value === "DEL") {

            programmingBackspace();
            return;
        }

        programmingWrite(value);
    };

    scientificGrid.appendChild(button);
});
    }


    const numberGrid =
        document.querySelector(".number-grid");

    if (numberGrid) {

        numberGrid.innerHTML = "";

        const keys = [
    "7", "8", "9",
    "4", "5", "6",
    "1", "2", "3",
    "0", "=", "Ans",
    "CLR", "NEG", "MOD"
];

        keys.forEach(value => {

    const button =
        document.createElement("button");

    button.textContent = value;

    button.onclick = function () {

        // ==============================
        // =
        // ==============================
        if (value === "=") {

            calculateProgrammingBases();
            return;
        }


        // ==============================
        // Ans
        // ==============================
        if (value === "Ans") {

            programmingWrite(
                String(
                    window.lastProgrammingResult ?? ""
                )
            );

            return;
        }


        // ==============================
        // CLR
        // ==============================
        if (value === "CLR") {

            programmingClear();
            return;
        }


        // ==============================
        // NEG
        // ==============================
        if (value === "NEG") {

            programmingToggleSign();
            return;
        }


        // ==============================
        // MOD
        // ==============================
        if (value === "MOD") {

            programmingWrite("%");
            return;
        }


        // ==============================
        // ط¨ط§ظ‚ظٹ ط§ظ„ط£ط²ط±ط§ط±
        // ==============================

        programmingWrite(value);
    };

    numberGrid.appendChild(button);
});

    }
};
