// ًں’» Programming - NEG
// ==========================================

window.programmingToggleSign = function () {

    const field =
        document.getElementById(
            window.activeProgrammingField
        );

    if (!field) return;

    if (!field.value) return;

    if (field.value.startsWith("-")) {

        field.value =
            field.value.slice(1);

    } else {

        field.value =
            "-" + field.value;
    }
};
