// ==========================================
// ًں§® ط­ط³ط§ط¨ ط§ظ„ظ…ظƒظ…ظ„ط§طھ ظˆط§ظ„ظ…طھظ…ظ…ط§طھ
// ==========================================

window.calculateProgrammingComplement = function () {

    const input =
        document.getElementById(
            "programmingComplementInput"
        );

    const type =
        document.getElementById(
            "programmingComplementType"
        )?.value;

    const result =
        document.getElementById(
            "programmingComplementResult"
        );

    if (!input || !result || !type) return;

    const value =
        input.value.trim();

    if (!value) {

        result.innerHTML =
            "â‌Œ ط£ط¯ط®ظ„ ط±ظ‚ظ…ظ‹ط§";

        return;
    }


    // ======================================
    // 1's ظˆ 2's Complement
    // ======================================

    if (
        type === "ones" ||
        type === "twos"
    ) {

        if (!/^[01]+$/.test(value)) {

            result.innerHTML =
                "â‌Œ ظٹط¬ط¨ ط£ظ† ظٹط­طھظˆظٹ ط§ظ„ط±ظ‚ظ… ط¹ظ„ظ‰ 0 ظˆ1 ظپظ‚ط·";

            return;
        }

        const ones =
            value
                .split("")
                .map(bit =>
                    bit === "0" ? "1" : "0"
                )
                .join("");

        let answer;

        if (type === "ones") {

            answer = ones;

        } else {

            answer =
                (
                    BigInt("0b" + ones) + 1n
                )
                .toString(2)
                .padStart(value.length, "0")
                .slice(-value.length);
        }

        result.innerHTML =
            `âœ… ط§ظ„ظ†طھظٹط¬ط© = ${answer}`;

        window.lastProgrammingResult =
            answer;

        return;
    }


    // ======================================
    // 9's Complement
    // ======================================

    if (type === "nines") {

        if (!/^[0-9]+$/.test(value)) {

            result.innerHTML =
                "â‌Œ ظ…ظƒظ…ظ„ 9 ظٹط­طھط§ط¬ ط±ظ‚ظ…ظ‹ط§ ط¹ط´ط±ظٹظ‹ط§";

            return;
        }

        const answer =
            value
                .split("")
                .map(digit =>
                    String(9 - Number(digit))
                )
                .join("");

        result.innerHTML =
            `âœ… ط§ظ„ظ†طھظٹط¬ط© = ${answer}`;

        window.lastProgrammingResult =
            answer;

        return;
    }


    // ======================================
    // 10's Complement
    // ======================================

    if (type === "tens") {

        if (!/^[0-9]+$/.test(value)) {

            result.innerHTML =
                "â‌Œ ظ…ظƒظ…ظ„ 10 ظٹط­طھط§ط¬ ط±ظ‚ظ…ظ‹ط§ ط¹ط´ط±ظٹظ‹ط§";

            return;
        }

        const nines =
            value
                .split("")
                .map(digit =>
                    String(9 - Number(digit))
                )
                .join("");

        const answer =
            (
                BigInt(nines) + 1n
            )
            .toString()
            .padStart(value.length, "0");

        result.innerHTML =
            `âœ… ط§ظ„ظ†طھظٹط¬ط© = ${answer}`;

        window.lastProgrammingResult =
            answer;
    }
};
