// ==========================================
// ًں§® ط­ط³ط§ط¨ ط§ظ„ط¹ظ…ظ„ظٹط§طھ ط§ظ„ط«ظ†ط§ط¦ظٹط©
// ==========================================

window.calculateBinaryArithmetic = function () {

    const fieldA =
        document.getElementById(
            "binaryArithmeticA"
        );

    const fieldB =
        document.getElementById(
            "binaryArithmeticB"
        );

    const operation =
        document.getElementById(
            "binaryArithmeticOperation"
        )?.value;

    const result =
        document.getElementById(
            "binaryArithmeticResult"
        );

    if (
        !fieldA ||
        !fieldB ||
        !result ||
        !operation
    ) {
        return;
    }

    const aText =
        fieldA.value.trim();

    const bText =
        fieldB.value.trim();

    if (
        !/^[01]+$/.test(aText) ||
        !/^[01]+$/.test(bText)
    ) {

        result.innerHTML =
            "â‌Œ ط£ط¯ط®ظ„ ط£ط±ظ‚ط§ظ…ظ‹ط§ ط«ظ†ط§ط¦ظٹط© طµط­ظٹط­ط©";

        return;
    }

    const a =
        BigInt("0b" + aText);

    const b =
        BigInt("0b" + bText);

    let answer;

    if (operation === "+") {

        answer = a + b;

    } else if (operation === "-") {

        answer = a - b;

    } else if (operation === "*") {

        answer = a * b;

    } else if (operation === "/") {

        if (b === 0n) {

            result.innerHTML =
                "â‌Œ ظ„ط§ ظٹظ…ظƒظ† ط§ظ„ظ‚ط³ظ…ط© ط¹ظ„ظ‰ طµظپط±";

            return;
        }

        answer = a / b;

    } else if (operation === "%") {

        if (b === 0n) {

            result.innerHTML =
                "â‌Œ ظ„ط§ ظٹظ…ظƒظ† MOD ط¹ظ„ظ‰ طµظپط±";

            return;
        }

        answer = a % b;
    }

    const decimalResult =
        answer.toString();

    const binaryResult =
        answer < 0n
            ? "-" + (-answer).toString(2)
            : answer.toString(2);

    result.innerHTML = `
        BIN = ${binaryResult}<br>
        DEC = ${decimalResult}
    `;

    window.lastProgrammingResult =
        answer;
};
