window.calculateHexArithmetic = function () {

    const fieldA =
        document.getElementById(
            "hexArithmeticA"
        );

    const fieldB =
        document.getElementById(
            "hexArithmeticB"
        );

    const operation =
        document.getElementById(
            "hexArithmeticOperation"
        )?.value;

    const result =
        document.getElementById(
            "hexArithmeticResult"
        );

    if (
        !fieldA ||
        !fieldB ||
        !operation ||
        !result
    ) {
        return;
    }

    const aText =
        fieldA.value.trim();

    const bText =
        fieldB.value.trim();

    if (
        !/^[0-9A-Fa-f]+$/.test(aText) ||
        !/^[0-9A-Fa-f]+$/.test(bText)
    ) {

        result.innerHTML =
            "â‌Œ ط£ط¯ط®ظ„ ط£ط±ظ‚ط§ظ… Hex طµط­ظٹط­ط©";

        return;
    }

    const a =
        BigInt("0x" + aText);

    const b =
        BigInt("0x" + bText);

    let answer;

    if (operation === "+") {

        answer = a + b;

    } else if (operation === "-") {

        answer = a - b;

    } else if (operation === "*") {

        answer = a * b;

    } else if (operation === "/") {

        if (b === 0n) {

            result.innerHTML =
                "â‌Œ ظ„ط§ ظٹظ…ظƒظ† ط§ظ„ظ‚ط³ظ…ط© ط¹ظ„ظ‰ طµظپط±";

            return;
        }

        answer = a / b;

    } else if (operation === "%") {

        if (b === 0n) {

            result.innerHTML =
                "â‌Œ ظ„ط§ ظٹظ…ظƒظ† MOD ط¹ظ„ظ‰ طµظپط±";

            return;
        }

        answer = a % b;
    }

    const hexAnswer =
        answer < 0n
            ? "-" + (-answer).toString(16).toUpperCase()
            : answer.toString(16).toUpperCase();

    result.innerHTML = `
        HEX = ${hexAnswer}<br>
        DEC = ${answer.toString()}
    `;

    window.lastProgrammingResult =
        answer;
};
