window.calculateAdvancedComplement = function () {

    const system =
        document.getElementById(
            "advancedComplementSystem"
        )?.value;

    const type =
        document.getElementById(
            "advancedComplementType"
        )?.value;

    const input =
        document.getElementById(
            "advancedComplementInput"
        );

    const result =
        document.getElementById(
            "advancedComplementResult"
        );

    if (!system || !type || !input || !result) {
        return;
    }

    const value =
        input.value.trim();

    if (!value) {

        result.innerHTML =
            "â‌Œ ط£ط¯ط®ظ„ ط±ظ‚ظ…ظ‹ط§";

        return;
    }

    // ======================================
    // ًںں  Octal
    // ======================================

    if (system === "octal") {

        if (!/^[0-7]+$/.test(value)) {

            result.innerHTML =
                "â‌Œ ط£ط¯ط®ظ„ ط±ظ‚ظ… Octal طµط­ظٹط­";

            return;
        }

        const n =
            BigInt("0o" + value);

        const base =
            8n ** BigInt(value.length);

        let answer;

        if (type === "sevens") {

            answer =
                (base - 1n) - n;

        } else {

            answer =
                (base - n) % base;
        }

        result.innerHTML = `
            OCT = ${answer.toString(8)}
            <br>
            DEC = ${answer.toString()}
        `;

        return;
    }


    // ======================================
    // ًںں£ Hexadecimal
    // ======================================

    if (system === "hex") {

        if (!/^[0-9A-Fa-f]+$/.test(value)) {

            result.innerHTML =
                "â‌Œ ط£ط¯ط®ظ„ ط±ظ‚ظ… Hex طµط­ظٹط­";

            return;
        }

        const n =
            BigInt("0x" + value);

        const base =
            16n ** BigInt(value.length);

        let answer;

        if (type === "fifteens") {

            answer =
                (base - 1n) - n;

        } else {

            answer =
                (base - n) % base;
        }

        result.innerHTML = `
            HEX = ${answer.toString(16).toUpperCase()}
            <br>
            DEC = ${answer.toString()}
        `;
    }
};

